(window.CareerPacks = window.CareerPacks || {}).UK = Object.assign({"code":"UK","name":"United Kingdom","flag":"\ud83c\uddec\ud83c\udde7","sym":"\u00a3","taxYear":"2026/27","holdTitle":"What your employer takes off before you are paid","source":"Pay figures are typical UK salaries from the original Dollar Book Career Guide. Tax: HMRC 2026/27 rates for an employee in England, Wales or Northern Ireland.","assume":"Single employee, one job, no pension, student loan or Scottish rates."}, {
  jobs: [{"t":"Hospital Doctor","s":"NHS","c":"Healthcare","k":80,"d":["Starts \u00a336,616 as a newly qualified Foundation doctor","Rises to \u00a380,693 as a senior registrar","Consultants earn \u00a3105,504-\u00a3139,882, often more with private work","Qualifications: GCSEs incl. sciences and maths \u2192 A-Levels (Biology, Chemistry + 1 more, top grades needed) \u2192 5-year Medicine degree \u2192 2-year Foundation Training \u2192 3-8 more years of specialty training depending on path"],"u":"https://en.wikipedia.org/wiki/Medicine"},{"t":"GP","s":"Family Doctor","c":"Healthcare","k":98,"d":["Salaried GPs typically earn \u00a368,000-\u00a3110,000","GP partners who co-own a practice can earn \u00a3140,000+ but take on financial risk","Qualifications: same medical degree route as hospital doctors, plus specialist GP training (3 more years) after Foundation Training"],"u":"https://en.wikipedia.org/wiki/General_practitioner"},{"t":"Registered Nurse","s":"NHS","c":"Healthcare","k":33,"d":["Starts around \u00a328,000-\u00a330,000 (Band 5)","Experienced nurses reach \u00a336,000-\u00a337,000 (Band 6)","Senior/specialist nurses can reach \u00a345,000+","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 3-year Nursing degree (BSc) \u2192 register with the Nursing and Midwifery Council"],"u":"https://en.wikipedia.org/wiki/Nursing"},{"t":"Dentist","s":"","c":"Healthcare","k":75,"d":["Average around \u00a351,807-\u00a375,000, experienced/private dentists significantly more","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Biology, Chemistry, top grades needed - highly competitive) \u2192 5-year Dentistry degree \u2192 register with the General Dental Council"],"u":"https://en.wikipedia.org/wiki/Dentistry"},{"t":"Paramedic","s":"NHS","c":"Healthcare","k":34,"d":["Starts around \u00a328,000-\u00a330,000","Experienced paramedics reach \u00a337,000-\u00a340,000+","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 3-year Paramedic Science degree (or apprenticeship route while working) \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Paramedic"},{"t":"Veterinary Surgeon","s":"","c":"Healthcare","k":50,"d":["Starts around \u00a333,000-\u00a338,000","Experienced vets reach \u00a350,000-\u00a365,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Biology, Chemistry + 1 more, very top grades needed - one of the most competitive degrees to get into) \u2192 5-6 year Veterinary Medicine degree \u2192 register with the Royal College of Veterinary Surgeons"],"u":"https://en.wikipedia.org/wiki/Veterinary_medicine"},{"t":"Radiographer","s":"NHS","c":"Healthcare","k":40,"d":["Starts around \u00a329,970-\u00a332,073 (Band 5)","Reaches \u00a339,043-\u00a347,084 after 2 years (Band 6)","Senior/reporting radiographers \u00a358,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Diagnostic or Therapeutic Radiography degree \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Radiographer"},{"t":"Physiotherapist","s":"NHS","c":"Healthcare","k":44,"d":["Starts around \u00a339,959 (Band 6, where most enter)","Reaches \u00a348,117 after 3 years","Private practice/sports physio \u00a335,000-\u00a370,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Physiotherapy (BSc) degree \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Physical_therapy"},{"t":"Care Worker/Support Worker","s":"","c":"Healthcare","k":23,"d":["Average around \u00a321,000-\u00a326,000","Senior care workers \u00a324,000-\u00a330,000","Registered Care Managers \u00a335,000-\u00a355,000","Qualifications: often no formal qualifications required to start - training (Care Certificate, NVQ) usually completed on the job","Honest note: one of the lowest-paid jobs here despite being genuinely essential and demanding work"],"u":"https://en.wikipedia.org/wiki/Care_work"},{"t":"Midwife","s":"NHS","c":"Healthcare","k":44,"d":["Starts around \u00a339,959 (Band 6, where most enter)","Reaches \u00a348,117 after 3 years, plus unsocial hours pay for nights/weekends","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Midwifery degree (BSc) \u2192 register with the Nursing and Midwifery Council"],"u":"https://en.wikipedia.org/wiki/Midwife"},{"t":"Pharmacist","s":"","c":"Healthcare","k":49,"d":["Typical range \u00a331,000-\u00a367,000, senior/specialist and independent pharmacy owners more","Qualifications: GCSEs incl. Chemistry \u2192 A-Levels (Chemistry required, Biology/Maths help) \u2192 4-year MPharm degree \u2192 1-year paid Foundation training year \u2192 register with the General Pharmaceutical Council"],"u":"https://en.wikipedia.org/wiki/Pharmacist"},{"t":"Optometrist","s":"","c":"Healthcare","k":60,"d":["Typical range \u00a332,000-\u00a388,000 depending on sector and whether self-employed/practice owner","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Physics, Maths, Biology helpful) \u2192 3-4 year Optometry degree \u2192 register with the General Optical Council"],"u":"https://en.wikipedia.org/wiki/Optometry"},{"t":"Clinical Psychologist","s":"NHS","c":"Healthcare","k":53,"d":["Enters at Band 7 (\u00a349,387-\u00a356,515)","Band 8a \u00a357,528-\u00a364,750","Senior consultant (8b/c) \u00a366,582-\u00a391,609","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Psychology helps) \u2192 3-year Psychology degree (must be British Psychological Society accredited) \u2192 3-year NHS-funded Doctorate in Clinical Psychology (DClinPsy) \u2192 one of the longest and most competitive routes here, often 6+ years total plus relevant experience just to get onto the doctorate"],"u":"https://en.wikipedia.org/wiki/Clinical_psychology"},{"t":"Occupational Therapist","s":"NHS","c":"Healthcare","k":43,"d":["Starts around \u00a332,073-\u00a339,043 (Band 5)","Reaches \u00a339,043-\u00a347,084 after 12-18 months (Band 6)","Average around \u00a342,557","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Occupational Therapy degree (BSc) \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Occupational_therapy"},{"t":"Speech & Language Therapist","s":"NHS","c":"Healthcare","k":44,"d":["Average around \u00a343,863, London around \u00a351,122","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Speech & Language Therapy degree (BSc) \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Speech-language_pathology"},{"t":"Psychiatrist","s":"NHS","c":"Healthcare","k":132,"d":["A medical doctor route, distinct from Clinical Psychologist elsewhere in this guide","Foundation \u00a341,226-\u00a347,610 \u2192 specialty training \u00a355,355-\u00a377,348 \u2192 Consultant \u00a3113,565-\u00a3150,569 (2026/27)","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Biology, Chemistry, top grades needed) \u2192 5-year Medicine degree \u2192 2-year Foundation Training \u2192 6 more years of psychiatry specialty training \u2192 one of the longest medical routes here"],"u":"https://en.wikipedia.org/wiki/Psychiatrist"},{"t":"Dietitian","s":"NHS","c":"Healthcare","k":41,"d":["Enters at Band 5 (\u00a332,073-\u00a339,043) \u2192 Band 6 \u00a339,959-\u00a348,117 \u2192 Band 7 \u00a349,387-\u00a356,515 \u2192 senior roles higher still","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-4 year Dietetics degree (BSc) \u2192 register with the Health and Care Professions Council","Legally protected title, unlike the unregulated \u201cnutritionist\u201d"],"u":"https://en.wikipedia.org/wiki/Dietitian"},{"t":"Strength & Conditioning Coach","s":"","c":"Healthcare","k":30,"d":["Distinct from Physiotherapist elsewhere in this guide - designs training programmes to build athletic performance and reduce injury risk, rather than treating injuries directly","Entry-level \u00a320,000-\u00a325,000 \u2192 mid-career \u00a325,000-\u00a334,000 \u2192 senior/elite roles \u00a347,000-\u00a380,000+, London considerably higher \u2192 Premier League academy roles often around \u00a326,000-\u00a330,000, first-team roles higher","Qualifications: GCSEs incl. sciences \u2192 A-Levels \u2192 Sports Science/Strength and Conditioning degree (BSc) \u2192 UKSCA accreditation adds real credibility \u2192 building a track record at academy/community level is the realistic route into elite sport, not starting there"],"u":"https://en.wikipedia.org/wiki/Strength_and_conditioning_coach"},{"t":"Dental Hygienist","s":"","c":"Healthcare","k":38,"d":["NHS pay \u00a330,279-\u00a344,962","Private practice often higher, frequently paid hourly (\u00a325-\u00a345/hour) or as a percentage of treatment fees","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 2-3 year Dental Hygiene diploma or degree \u2192 register with the General Dental Council"],"u":"https://en.wikipedia.org/wiki/Dental_hygienist"},{"t":"Podiatrist/Chiropodist","s":"NHS","c":"Healthcare","k":44,"d":["Band 5-7 (\u00a332,073-\u00a356,515)","Many run private practices where earnings vary with caseload","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 3-year Podiatry degree (BSc) \u2192 register with the Health and Care Professions Council"],"u":"https://en.wikipedia.org/wiki/Podiatry"},{"t":"Dispensing Optician","s":"","c":"Healthcare","k":32,"d":["Average around \u00a330,000-\u00a335,000","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 General Optical Council course \u2192 Professional Qualifying Examination from the Association of British Dispensing Opticians","Running your own practice significantly increases earning potential"],"u":"https://en.wikipedia.org/wiki/Optician"},{"t":"Clinical Research Associate","s":"CRA","c":"Healthcare","k":40,"d":["Pharmaceutical/clinical trials","Average around \u00a339,993, typical range \u00a333,409-\u00a348,243, top earners \u00a357,611","Monitors clinical trials for pharmaceutical companies and contract research organisations, ensuring compliance and patient safety","Qualifications: GCSEs incl. sciences \u2192 A-Levels \u2192 life sciences degree \u2192 Good Clinical Practice (GCP) certification adds real value \u2192 specialising in a therapeutic area like oncology boosts pay further"],"u":"https://en.wikipedia.org/wiki/Clinical_research_associate"},{"t":"Electrician","s":"","c":"Trades","k":40,"d":["Apprentices start around \u00a313,500-\u00a318,500 while training and earning","Newly qualified \u00a328,000-\u00a335,000","Experienced/specialist electricians \u00a342,000-\u00a355,000+, self-employed can exceed \u00a370,000","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a 4-year paid apprenticeship (earn while you learn, no university needed) \u2192 AM2 assessment \u2192 ECS Gold Card"],"u":"https://en.wikipedia.org/wiki/Electrician"},{"t":"Plumber/Gas Engineer","s":"","c":"Trades","k":38,"d":["Apprentices start around \u00a316,000-\u00a321,000 while training and earning","Newly qualified \u00a329,000-\u00a335,000","Experienced/self-employed plumbers \u00a345,000-\u00a360,000+","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a 2-4 year paid apprenticeship (no university needed) \u2192 Gas Safe registration required for boiler/gas work"],"u":"https://en.wikipedia.org/wiki/Plumbing"},{"t":"Carpenter/Joiner","s":"","c":"Trades","k":37,"d":["Newly qualified around \u00a325,000-\u00a330,000","Experienced/specialist bench joiners \u00a335,000-\u00a345,000+, self-employed can exceed \u00a355,000","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed)"],"u":"https://en.wikipedia.org/wiki/Carpentry"},{"t":"Hairdresser","s":"","c":"Trades","k":20,"d":["Median around \u00a318,500-\u00a320,347, one of the lower-paid trades here","Self-employed chair-rental or salon ownership can improve this significantly","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed)","Honest note: a genuinely accessible trade to enter, but pay is modest unless you build your own clientele or business"],"u":"https://en.wikipedia.org/wiki/Hairdresser"},{"t":"Bricklayer","s":"","c":"Trades","k":36,"d":["Newly qualified \u00a330,000-\u00a338,000","Average around \u00a336,000-\u00a340,000","Senior/business owners can exceed \u00a365,000","Qualifications: GCSEs \u2192 Level 2/3 NVQ (Trowel Occupations) via a paid apprenticeship (no university needed) \u2192 CSCS card required on site \u2192 genuinely in high demand across the UK construction industry"],"u":"https://en.wikipedia.org/wiki/Bricklayer"},{"t":"Painter & Decorator","s":"","c":"Trades","k":33,"d":["Apprentices start \u00a322,000-\u00a327,000","Average around \u00a329,000-\u00a337,000","Self-employed commercial work \u00a330,000-\u00a345,000+","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 one of the more accessible trades to enter, though pay is modest compared to electrician/plumber unless specialising in high-end commercial finishes"],"u":"https://en.wikipedia.org/wiki/Painter_and_decorator"},{"t":"Roofer","s":"","c":"Trades","k":40,"d":["Self-employed typical earnings \u00a335,000-\u00a355,000, with real seasonal variation (busier and better-paid in summer)","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 CSCS card required on site"],"u":"https://en.wikipedia.org/wiki/Roofer"},{"t":"Leadworker","s":"","c":"Trades","k":42,"d":["Distinct from Roofer elsewhere in this guide - a specialist working with lead sheet on flashings, guttering and full roof coverings, especially heritage and conservation buildings","Newly trained \u00a328,000 \u2192 experienced specialists \u00a340,000-\u00a360,000+","Genuinely rare, high-value skill - the number of qualified leadworkers is shrinking even as demand for heritage restoration holds steady","Qualifications: GCSEs \u2192 NVQ Level 2 Lead and Hard Metal Roofing via a paid apprenticeship (no university needed) \u2192 the Leadworker Register (Levels 1-4) formally recognises competence, with Level 4 covering advanced heritage detailing"],"u":"https://en.wikipedia.org/wiki/Lead_sheet"},{"t":"Piano Tuner","s":"","c":"Trades","k":22,"d":["Average around \u00a320,482, typical range \u00a320,000-\u00a329,000 \u2192 established self-employed tuners with a strong client list and concert hall/institutional contracts can earn more","A genuinely niche, highly specialised skill requiring excellent hearing and patience","Qualifications: no formal qualifications required \u2192 dedicated piano tuning courses/apprenticeship with an established tuner, typically 1-2 years to become proficient \u2192 Pianoforte Tuners\u2019 Association membership recognised industry-wide"],"u":"https://en.wikipedia.org/wiki/Piano_tuning"},{"t":"Butcher","s":"","c":"Trades","k":29,"d":["Median around \u00a329,000, typical range \u00a322,300-\u00a333,000 \u2192 experienced/specialist cutters with strong site or skill premiums can earn more","Genuinely one of the oldest crafts in the world, requiring dexterous knife skills to make every carcase profitable","Qualifications: no formal qualifications required to start \u2192 Level 2 Butcher Apprenticeship via a paid apprenticeship (no university needed) \u2192 the Institute of Meat awards M.Inst.M status on completion, genuine professional recognition"],"u":"https://en.wikipedia.org/wiki/Butcher"},{"t":"Baker","s":"","c":"Trades","k":27,"d":["Average around \u00a326,500, starting from \u00a315,800 \u2192 experienced artisan/specialist bakers can reach \u00a345,000, Head Bakers at top venues higher still","Genuine progression route through Pastry Chef, Bakery Manager, or eventually running your own bakery","Qualifications: no formal qualifications required to start \u2192 Level 2/3 Bakery apprenticeship via City & Guilds or college route (no university needed) \u2192 early starts and physical, repetitive work are a genuine trade-off for a creative, hands-on craft"],"u":"https://en.wikipedia.org/wiki/Baker"},{"t":"Cobbler","s":"Shoe Repairer","c":"Trades","k":24,"d":["Realistic range \u00a318,000-\u00a328,000, top specialists in bespoke repair, orthopaedic work or leather goods restoration can exceed \u00a335,000-\u00a340,000","A genuinely traditional trade that has shrunk with mass-market footwear, but real niche opportunities remain in bespoke repair and restoration","Qualifications: no formal qualifications required \u2192 learns almost entirely through hands-on apprenticeship alongside an established cobbler, typically several years to master \u2192 building a loyal local client base matters more than any certificate"],"u":"https://en.wikipedia.org/wiki/Shoemaking"},{"t":"Bespoke Saddler","s":"","c":"Trades","k":25,"d":["Median around \u00a324,938 (official UK government occupational standard)","Makes, alters and repairs saddles, bridles and harnesses using traditional handcrafting methods, taking measurements directly from the horse for a genuine bespoke fit","Part of a UK equestrian industry with 27 million people taking a genuine interest","Qualifications: no formal qualifications required to start, training delivered on the job \u2192 Level 3 Bespoke Saddler Apprenticeship via the Society of Master Saddlers \u2192 excellent hand-eye coordination and manual dexterity essential"],"u":"https://en.wikipedia.org/wiki/Saddler"},{"t":"Bespoke Tailor","s":"","c":"Trades","k":23,"d":["Median around \u00a323,348 (official UK government occupational standard)","The UK has a genuinely world-famous reputation for bespoke tailoring - British tailors on Savile Row have dressed everyone from royalty to rock stars","Cuts and constructs garments to a unique pattern for each individual client, part of the sustainable \u201cslow fashion\u201d approach","Qualifications: no formal qualifications required to start \u2192 Level 5 Bespoke Cutter and Tailor apprenticeship (Higher Technical Occupation, a genuinely advanced route for a trade) \u2192 years of practice needed to master precision cutting and construction"],"u":"https://en.wikipedia.org/wiki/Tailor"},{"t":"Silversmith","s":"tableware, flatware, ecclesiastical pieces, functional vessels","c":"Trades","k":27,"d":["Distinct from Jeweller/Goldsmith elsewhere in this guide - crafts larger-scale silverware rather than small jewellery items, using different forming and raising techniques","Apprentices \u00a312,000-\u00a318,000 across a 4-year apprenticeship \u2192 employed silversmith \u00a322,000-\u00a334,000 in the first few years, rising further with reputation and skill","Sheffield holds a genuine 150+ year heritage in silversmithing and cutlery craftsmanship","Qualifications: no formal qualifications required to start \u2192 Level 3 Jewellery, Silversmithing and Allied Trades apprenticeship (2-4 years)"],"u":"https://en.wikipedia.org/wiki/Silversmith"},{"t":"Shipwright","s":"","c":"Trades","k":40,"d":["Distinct from Boat Builder elsewhere in this guide - builds and repairs large naval/commercial vessels at major defence shipyards rather than fitting out leisure boats","Apprentices \u00a315,000-\u00a320,000 \u2192 average around \u00a334,682, typical range \u00a325,651-\u00a338,473 \u2192 experienced shipwrights at major shipyards (BAE Systems, Babcock) commonly earn \u00a339,000-\u00a351,500+","Genuine historic heritage - Devonport naval dockyard was founded in 1691","Qualifications: no degree needed \u2192 3-4 year apprenticeship with a shipyard, naval repair facility or the Royal Navy \u2192 can specialise in traditional timber, GRP/fibreglass or steelwork"],"u":"https://en.wikipedia.org/wiki/Shipwright"},{"t":"Mobile Crane Operator","s":"","c":"Trades","k":40,"d":["Distinct from both the general Plant Operator and Port Crane Operator elsewhere in this guide - operates large truck-mounted or crawler cranes that travel between different construction and industrial sites, rather than fixed excavators or dockside gantry cranes","Genuinely wide range depending on setting: entry/assistant \u00a325,000-\u00a335,000 \u2192 established \u00a338,000-\u00a355,000 \u2192 senior/specialist roles in offshore, nuclear or major infrastructure work \u00a355,000-\u00a390,000+ \u2192 day rates commonly \u00a3200-\u00a3250+ for contract work","Qualifications: no degree needed \u2192 CPCS or NPORS crane-specific ticket \u2192 the exact training route depends on crane type and employer"],"u":"https://en.wikipedia.org/wiki/Mobile_crane"},{"t":"Welder","s":"","c":"Trades","k":45,"d":["Self-employed typical earnings \u00a340,000-\u00a365,000","Coded welders working on major infrastructure projects earn more still","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 welding certification/coding (e.g. to ISO or ASME standards) significantly increases pay"],"u":"https://en.wikipedia.org/wiki/Welding"},{"t":"Plasterer","s":"","c":"Trades","k":42,"d":["Self-employed day rate \u00a3180-\u00a3300, higher in London or for specialist rendering/heritage work","Piece-work paid by the square metre can boost earnings for fast, skilled tradespeople","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 genuinely in strong demand, always described as \u201calways needed\u201d across the trade"],"u":"https://en.wikipedia.org/wiki/Plasterer"},{"t":"Tiler","s":"","c":"Trades","k":32,"d":["Average around \u00a331,562","Typical range \u00a318,000-\u00a355,000 depending on experience and whether self-employed \u2192 skilled commercial tilers on day rates can earn considerably more","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 CSCS card required on most sites"],"u":"https://en.wikipedia.org/wiki/Tile"},{"t":"Glazier","s":"","c":"Trades","k":36,"d":["Realistic range \u00a328,000-\u00a345,000","Self-employed day rates \u00a3170-\u00a3300, higher for specialist commercial glazing (shopfronts, curtain walling, lead fitting)","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 accuracy matters enormously - a wrong measurement or damaged unit costs real money"],"u":"https://en.wikipedia.org/wiki/Glazier"},{"t":"Scaffolder","s":"","c":"Trades","k":37,"d":["Employed qualified scaffolders typically earn \u00a330,000-\u00a344,000","Supervisory/contracts management roles \u00a350,000-\u00a365,000","Self-employed day rates \u00a3180-\u00a3300","Qualifications: GCSEs \u2192 CISRS (Construction Industry Scaffolders Record Scheme) qualification via a paid apprenticeship (no university needed) \u2192 physical, working-at-height role, well compensated relative to the training investment required"],"u":"https://en.wikipedia.org/wiki/Scaffolding"},{"t":"Locksmith","s":"","c":"Trades","k":33,"d":["Realistic range \u00a328,000-\u00a350,000+","Employed/mobile technicians typically high-twenties to high-thirties","Self-employed locksmiths in busy towns can earn more by controlling their own call-out pricing","Qualifications: GCSEs \u2192 practical training and supervised experience (no fixed apprenticeship route, no university needed) \u2192 building a strong local reputation genuinely matters more than formal qualifications here"],"u":"https://en.wikipedia.org/wiki/Locksmithing"},{"t":"Beautician","s":"","c":"Trades","k":28,"d":["Average around \u00a327,992-\u00a330,290","Qualifications: GCSEs \u2192 Level 2/3 NVQ in Beauty Therapy via a paid apprenticeship (no university needed) \u2192 self-employed or mobile beauticians who build a strong client base can earn considerably more than salon-employed staff"],"u":"https://en.wikipedia.org/wiki/Beauty_salon"},{"t":"HVAC Engineer","s":"heating, ventilation, air conditioning","c":"Trades","k":43,"d":["Realistic range \u00a332,000-\u00a355,000+, London higher still","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 F-Gas Category 1 certification is the single biggest pay lever, opening up air conditioning and refrigeration work \u2192 heat pump specialism increasingly valuable as demand grows"],"u":"https://en.wikipedia.org/wiki/HVAC"},{"t":"Car/Vehicle Mechanic","s":"","c":"Trades","k":32,"d":["Genuine 4-level progression: Level 1 apprentices/trainees high-teens to low \u00a320,000s \u2192 Level 2 newly qualified low-to-mid \u00a320,000s \u2192 Level 3 experienced low-to-mid \u00a330,000s \u2192 Level 4 senior/diagnostic specialists \u00a340,000+","Overall average around \u00a340,000","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 specialising in diagnostics or a specific manufacturer brand lifts pay further \u2192 skills learned here transfer directly from the REME military route elsewhere in this guide"],"u":"https://en.wikipedia.org/wiki/Automobile_repair_shop"},{"t":"EV Technician","s":"Electric Vehicle","c":"Trades","k":35,"d":["An add-on specialism to Car Mechanic elsewhere in this guide rather than a separate trade - certified to safely work on high-voltage systems","Average around \u00a329,000-\u00a340,000+, EV-qualified technicians typically earn 10-20% more than standard mechanics doing the same job","A genuinely compelling skills-gap story: only around 20-26% of UK technicians currently hold EV qualifications, but the industry needs roughly 200,000 qualified by 2035 given the coming petrol/diesel sales ban \u2192 real career insurance for anyone entering the motor trade now","Qualifications: standard Car Mechanic route first \u2192 IMI Level 2-4 EV qualification, often completed in just a few days, costing \u00a3500-\u00a32,000 (sometimes funded by the employer)"],"u":"https://en.wikipedia.org/wiki/Electric_vehicle"},{"t":"MOT Tester","s":"","c":"Trades","k":35,"d":["Another add-on qualification to Car Mechanic elsewhere in this guide rather than a separate trade - legally certified to carry out the annual MOT roadworthiness test","Typical range \u00a324,000-\u00a338,000, average around \u00a335,417","Qualifications: standard Car Mechanic route first (usually 2+ years\u2019 experience) \u2192 DVSA-approved MOT tester qualification, a formal legal requirement to test vehicles \u2192 a genuine, marketable specialism that most garages need on staff"],"u":"https://en.wikipedia.org/wiki/MOT_test"},{"t":"Tyre Fitter","s":"","c":"Trades","k":27,"d":["Average around \u00a323,900-\u00a330,500, typical range \u00a320,500-\u00a332,000 \u2192 experienced, commercial or mobile tyre fitters can exceed \u00a340,000","Fits, repairs and balances tyres, and checks wheel alignment - physically demanding, high-turnover work","Qualifications: no formal qualifications required to start \u2192 IMI or City & Guilds tyre fitting qualifications available via a paid apprenticeship \u2192 a genuinely accessible entry point into the wider motor trade"],"u":"https://en.wikipedia.org/wiki/Tire"},{"t":"HGV Mechanic/Technician","s":"","c":"Trades","k":34,"d":["Distinct from Car Mechanic elsewhere in this guide - services heavy goods vehicles rather than cars, genuinely higher-paying due to the specialised systems involved","Average around \u00a332,864-\u00a334,074","Typical range \u00a328,000-\u00a352,743, experienced techs with shift allowances often \u00a342,000-\u00a352,000, top earners exceed \u00a356,500","Qualifications: GCSEs \u2192 Level 2/3 Heavy Vehicle Service and Maintenance Technician apprenticeship (2-4 years, no university needed) \u2192 specialising in engine diagnostics or going self-employed increases earning potential further"],"u":"https://en.wikipedia.org/wiki/Truck"},{"t":"Boat Builder","s":"","c":"Trades","k":30,"d":["Realistic range \u00a324,000-\u00a342,000","Apprentices start around \u00a316,372 in year one, rising through a 4-year training programme","Qualifications: GCSEs \u2192 Level 3 Boatbuilding apprenticeship (no university needed) \u2192 skilled traditional joinery work fitting out cabins, galleys and interiors on everything from sailing boats to luxury motor yachts"],"u":"https://en.wikipedia.org/wiki/Boat_building"},{"t":"Stonemason","s":"","c":"Trades","k":32,"d":["Average around \u00a331,600-\u00a334,500, London higher around \u00a344,000","Qualifications: GCSEs \u2192 Level 2/3 NVQ via a paid apprenticeship (no university needed) \u2192 heritage/cathedral restoration work is a genuinely distinctive specialism within this trade, often highly sought after and better paid"],"u":"https://en.wikipedia.org/wiki/Stonemasonry"},{"t":"Jeweller/Goldsmith","s":"","c":"Trades","k":30,"d":["Average around \u00a328,992-\u00a334,119 \u2192 major retailers pay \u00a318,525 (supervisor) up to \u00a332,500 (store manager)","Genuine hands-on craft combining design, repair and precision metalwork with diamonds and precious metals","Qualifications: no degree required \u2192 many major jewellers run their own apprenticeship schemes \u2192 previous experience or relevant City & Guilds qualifications help, but the working route (learning on the job) is well established and respected in this trade"],"u":"https://en.wikipedia.org/wiki/Jeweller"},{"t":"Watchmaker/Horologist","s":"","c":"Trades","k":30,"d":["Newly qualified \u00a318,000-\u00a322,000 \u2192 experienced with specialist skills \u00a325,000-\u00a340,000 \u2192 specialists working for luxury Swiss brands can exceed this considerably","A genuinely niche, highly precise craft - steady demand as older watchmakers retire and the luxury watch market keeps growing","Qualifications: no degree required \u2192 Watchmaker Level 3 Advanced Apprenticeship (2 years) or the British School of Watchmaking\u2019s 2-year course (some brands pay the course fees) \u2192 British Horological Institute membership recognised industry-wide"],"u":"https://en.wikipedia.org/wiki/Watchmaker"},{"t":"Cabinet Maker","s":"","c":"Trades","k":33,"d":["Distinct from Carpenter elsewhere in this guide - specialises in fine furniture rather than site construction","Average around \u00a333,407, typical range \u00a326,000-\u00a342,000 \u2192 bespoke/heritage restoration specialists command premium rates","Qualifications: GCSEs \u2192 Level 2/3 Carpentry & Joinery NVQ via a paid apprenticeship (no university needed) \u2192 restoring antique furniture or building bespoke pieces for private clients is a genuinely respected specialism within this trade"],"u":"https://en.wikipedia.org/wiki/Cabinetmaking"},{"t":"Toolmaker / Tool and Die Maker","s":"","c":"Trades","k":32,"d":["Apprentices start around \u00a314,500-\u00a320,500 \u2192 qualified toolmaker \u00a330,000-\u00a335,000 \u2192 specialist/senior roles up to \u00a342,000+","Designs, makes and maintains the precision tools, dies, jigs and moulds used across manufacturing - aerospace, automotive and defence industries all depend on this trade","Qualifications: GCSEs incl. Maths \u2192 Level 3 Engineering Technician Apprenticeship (3-4 years, no university needed) \u2192 genuinely exacting, high-precision work where a fraction of a millimetre matters"],"u":"https://en.wikipedia.org/wiki/Toolmaker"},{"t":"Commercial/Saturation Diver","s":"","c":"Trades","k":42,"d":["Broad average around \u00a331,057, masking an enormous real range: inshore instructors from \u00a316,000, experienced offshore/police/forces divers \u00a322,500-\u00a340,000, top North Sea saturation divers up to \u00a3150,000","North Sea day rates around \u00a3600/day under the industry ODIA agreement","Qualifications: no degree needed \u2192 HSE-approved commercial diving qualification \u2192 one of the most physically and psychologically demanding jobs in this whole app, with real health risks (decompression sickness) alongside the exceptional top-end pay"],"u":"https://en.wikipedia.org/wiki/Commercial_diver"},{"t":"Offshore Oil Rig Worker","s":"","c":"Trades","k":60,"d":["A genuine career ladder on a 2-on-2-off rotation: entry-level Roustabout around \u00a333,000/year (day rate \u00a3180-220) \u2192 time-served technicians \u00a368,000-\u00a3100,000 \u2192 Offshore Installation Manager (OIM) \u00a3135,000-\u00a3220,000, day rate up to \u00a31,200","Food, accommodation and helicopter travel typically covered on top of pay","Qualifications: no degree needed to start as a Roustabout \u2192 progression through trade-specific tickets (mechanical, electrical, instrument) lifts pay significantly \u2192 genuinely one of the highest-paid routes in this app with no degree required at any stage"],"u":"https://en.wikipedia.org/wiki/Roughneck"},{"t":"Offshore Wind Turbine Technician","s":"","c":"Trades","k":55,"d":["Day rates around \u00a3300-450, working out to roughly \u00a355,000-\u00a382,000/year on a typical offshore rotation","A rapidly growing field as the UK expands offshore wind capacity","Qualifications: no degree needed \u2192 Global Wind Organisation (GWO) safety training and a Level 3 apprenticeship \u2192 genuinely strong long-term demand given the UK\u2019s renewable energy targets"],"u":"https://en.wikipedia.org/wiki/Wind_turbine_technician"},{"t":"Manufacturing/Assembly Line Worker","s":"","c":"Trades","k":24,"d":["Median around \u00a324,000-\u00a325,000","Qualifications: no formal qualifications required to start \u2192 progression to Team Leader or Factory Manager (average \u00a335,205) available without a degree \u2192 genuinely accessible entry point into manufacturing, from cars to consumer goods"],"u":"https://en.wikipedia.org/wiki/Assembly_line"},{"t":"Pharmaceutical Production Operator","s":"","c":"Trades","k":27,"d":["Distinct from Clinical Research Associate elsewhere in this guide - manufactures medicines rather than testing them","Typical range \u00a326,300-\u00a327,890","Works under strict Good Manufacturing Practice (GMP) and health and safety regulations","Qualifications: no degree required to start \u2192 on-the-job training in GMP/GCP/COSHH compliance \u2192 a genuinely accessible entry point into the pharmaceutical industry without a science degree"],"u":"https://en.wikipedia.org/wiki/Good_manufacturing_practice"},{"t":"Construction Labourer/Groundworker","s":"roads, bridges, infrastructure","c":"Trades","k":30,"d":["Entry-level \u00a323,000-\u00a325,000 \u2192 with a CSCS card and experience \u00a328,000-\u00a332,000 \u2192 senior/specialist can exceed \u00a335,000-\u00a340,000, some groundworkers reach \u00a360,000 over time","Qualifications: no formal qualifications required to start \u2192 CSCS card required for site access \u2192 the physical foundation-laying work underpinning every major infrastructure project"],"u":"https://en.wikipedia.org/wiki/Construction_worker"},{"t":"Heavy Plant/Machinery Operator","s":"excavators, cranes, on major road and infrastructure projects","c":"Trades","k":33,"d":["Average around \u00a332,500-\u00a334,000","Day rates \u00a3200-\u00a3320 depending on machine size and region","Qualifications: no degree needed \u2192 a CPCS or NPORS plant ticket is described as the single biggest earnings lever available to a construction labourer \u2192 genuinely one of the clearest, fastest routes to a real pay rise in the whole trades sector"],"u":"https://en.wikipedia.org/wiki/Heavy_equipment"},{"t":"Teaching Assistant","s":"","c":"Education","k":20,"d":["Starts from around \u00a320,000","Qualifications: no formal qualifications required to start, though a Level 2/3 Teaching Assistant qualification is desirable \u2192 term-time only contracts (school holidays off) \u2192 a genuinely accessible entry point into education without a degree"],"u":"https://en.wikipedia.org/wiki/Teaching_assistant"},{"t":"SEN Teaching Assistant","s":"Special Educational Needs","c":"Education","k":22,"d":["Distinct from the general Teaching Assistant elsewhere in this guide - supports pupils with additional learning needs one-to-one or in small groups","Entry-level \u00a318,500-\u00a322,000 \u2192 mid-level \u00a322,000-\u00a324,500 \u2192 HLTA-status SEN specialists \u00a324,000-\u00a330,500, London higher still","Qualifications: no formal qualifications required to start \u2192 Level 3 Award in Supporting Teaching and Learning is the single highest-leverage qualification for pay progression \u2192 genuinely meaningful, patient-intensive work"],"u":"https://en.wikipedia.org/wiki/Special_education"},{"t":"School Counsellor","s":"","c":"Education","k":26,"d":["Typical range \u00a325,000-\u00a333,000, NJC Scale posts often around \u00a328,000-\u00a335,000 pro rata for term-time contracts","Supports students\u2019 emotional wellbeing, resilience and mental health, often working alongside SENCOs and pastoral teams","Qualifications: GCSEs \u2192 A-Levels \u2192 a recognised counselling qualification and professional accreditation (BACP or UKCP) required \u2192 usually needs several years of supervised practice before working independently with young people"],"u":"https://en.wikipedia.org/wiki/School_counselor"},{"t":"Nursery Manager","s":"","c":"Education","k":33,"d":["Distinct from Nursery Worker elsewhere in this guide - runs the whole early years setting rather than working directly with a single group of children","Typical range \u00a330,000-\u00a336,700, London higher, up to \u00a342,000-\u00a345,000","Balances safeguarding, staffing, occupancy, compliance and budgets alongside the educational side","Qualifications: no degree required \u2192 usually builds up from Nursery Worker through Deputy Manager \u2192 Level 3/5 Early Years qualifications plus management experience"],"u":"https://en.wikipedia.org/wiki/Nursery_(institution)"},{"t":"Youth Worker","s":"","c":"Education","k":27,"d":["Average around \u00a325,900-\u00a328,800, typical range \u00a320,800-\u00a334,000","Supports young people\u2019s personal, social and educational development outside the formal classroom, often through youth clubs, outreach or council-run programmes","Qualifications: GCSEs \u2192 A-Levels not always required \u2192 Level 2/3 Youth Work qualification, or a degree route (JNC-recognised) for more senior positions \u2192 genuinely meaningful work often based in the community rather than a school building"],"u":"https://en.wikipedia.org/wiki/Youth_work"},{"t":"Nursery Worker","s":"early years childcare","c":"Education","k":19,"d":["Average around \u00a319,000, one of the lowest-paid roles in this app despite the genuine skill and responsibility of caring for very young children","Qualifications: GCSEs \u2192 Level 2/3 Early Years qualification (CACHE or equivalent) \u2192 no degree needed, though Qualified Teacher Status opens up nursery/reception teaching roles instead"],"u":"https://en.wikipedia.org/wiki/Nursery_(institution)"},{"t":"Primary School Teacher","s":"","c":"Education","k":39,"d":["Starts around \u00a332,916 (Early Career Teacher) \u2192 average around \u00a339,421 \u2192 upper pay scale \u00a340,000-\u00a349,000","Qualifications: GCSEs \u2192 A-Levels \u2192 3-year Bachelor\u2019s degree \u2192 1-year PGCE (or School Direct/apprenticeship route) \u2192 Qualified Teacher Status"],"u":"https://en.wikipedia.org/wiki/Primary_education"},{"t":"Secondary School Teacher","s":"","c":"Education","k":41,"d":["Starts around \u00a331,626 (Main Pay Range)","Experienced teachers reach \u00a342,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 3-year Bachelor\u2019s degree in your subject \u2192 1-year PGCE teacher training (or paid School Direct/apprenticeship route) \u2192 Qualified Teacher Status"],"u":"https://en.wikipedia.org/wiki/Teacher"},{"t":"Headteacher","s":"","c":"Education","k":75,"d":["Leadership pay range typically \u00a350,000-\u00a375,000+, varies significantly with school size and location, London higher still","Qualifications: same QTS route as any teacher, followed by years of experience and often a National Professional Qualification for Headship (NPQH) before appointment"],"u":"https://en.wikipedia.org/wiki/Head_teacher"},{"t":"SENCO","s":"Special Educational Needs Coordinator","c":"Education","k":39,"d":["Average around \u00a339,072, with London and TLR allowances pushing this considerably higher, sometimes past \u00a350,000","Qualifications: same QTS route as any teacher \u2192 minimum 1 year classroom teaching experience \u2192 National Award for SEN Coordination \u2192 leads a school\u2019s whole approach to supporting pupils with additional needs"],"u":"https://en.wikipedia.org/wiki/Special_educational_needs_coordinator"},{"t":"University Lecturer","s":"","c":"Education","k":50,"d":["New lecturers (Grade 7) \u00a345,585-\u00a354,395","Senior lecturers (Grade 8) \u00a355,755-\u00a367,348","Qualifications: GCSEs \u2192 A-Levels \u2192 undergraduate degree (3-4 years) \u2192 PhD (3-4 years, usually essential) \u2192 postdoctoral research experience before landing a permanent lectureship \u2192 one of the longest routes here, often 10+ years post-18"],"u":"https://en.wikipedia.org/wiki/Lecturer"},{"t":"Further Education College Lecturer","s":"FE","c":"Education","k":33,"d":["Distinct from University Lecturer elsewhere in this guide","Average around \u00a332,852, typical range \u00a328,035-\u00a344,397","Qualifications: GCSEs \u2192 A-Levels \u2192 degree or significant vocational experience in your subject \u2192 a teaching qualification such as PGCE (FE) or DET, often completed while already teaching \u2192 a genuinely more accessible route than the PhD-heavy university lecturer path"],"u":"https://en.wikipedia.org/wiki/Further_education"},{"t":"Oxbridge College Don/Fellow","s":"","c":"Education","k":60,"d":["Distinct from the general University Lecturer elsewhere in this guide - a joint appointment between a university department and an individual college","Associate Professor scale \u00a347,000-\u00a378,000","Genuinely more than the number suggests: free or subsidised accommodation, meals in the college dining hall, and dedicated research funds add real value beyond salary","Qualifications: GCSEs \u2192 A-Levels \u2192 undergraduate degree \u2192 PhD \u2192 postdoctoral research \u2192 among the most competitive academic appointments in the UK, requiring a truly exceptional research record"],"u":"https://en.wikipedia.org/wiki/Don_(honorific)"},{"t":"School Librarian","s":"","c":"Education","k":22,"d":["Genuinely low-paid role, typical range \u00a317,000-\u00a327,000, many posts term-time only giving actual pay well below the headline full-time-equivalent figure","Manages library resources, supports academic study and fosters literacy and curiosity across the school","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required, though a librarianship qualification (or working toward one) helps \u2192 genuinely meaningful work with modest pay relative to the responsibility involved"],"u":"https://en.wikipedia.org/wiki/Librarian"},{"t":"School Careers Advisor","s":"","c":"Education","k":20,"d":["Full-time equivalent \u00a338,220-\u00a341,771, though many posts are genuinely part-time and term-time only, giving an actual annual pay of around \u00a317,770-\u00a319,421","Guides students toward post-16/post-18 pathways - further education, apprenticeships or employment","Qualifications: GCSEs \u2192 A-Levels \u2192 Level 6 Qualification in Career Guidance and Development (not always essential to start) \u2192 genuinely meaningful work shaping young people\u2019s next steps"],"u":"https://en.wikipedia.org/wiki/Career_counseling"},{"t":"Peripatetic/Private Music Teacher","s":"","c":"Education","k":33,"d":["Distinct from Secondary School Teacher elsewhere in this guide - travels between schools or teaches privately, one-to-one or small groups on a specific instrument or voice","Average around \u00a333,000-\u00a334,000, range \u00a322,000-\u00a352,000","Most work self-employed or hourly-paid - Musicians\u2019 Union recommends a minimum \u00a344/hour for private lessons","Qualifications: GCSEs \u2192 A-Levels \u2192 grade 8 or degree-level proficiency on the instrument taught, formal teaching qualification not always essential"],"u":"https://en.wikipedia.org/wiki/Music_education"},{"t":"Driving Instructor","s":"ADI","c":"Education","k":40,"d":["Distinct from Driving Examiner elsewhere in this guide - around 95% are self-employed sole traders, not employees","Newly qualified on a franchise \u00a325,000-\u00a335,000 net \u2192 established regional instructor \u00a336,000-\u00a348,000 \u2192 London/South East premium-rate instructors \u00a346,000-\u00a364,000 \u2192 intensive course specialists \u00a360,000-\u00a3100,000+","Qualifications: no degree needed \u2192 3-part DVSA Approved Driving Instructor (ADI) qualification, costing \u00a32,000-\u00a35,000 to complete - a genuine upfront cost, like Pilot and Barrister elsewhere in this guide"],"u":"https://en.wikipedia.org/wiki/Driving_instructor"},{"t":"Exam Marker/Moderator","s":"","c":"Education","k":30,"d":["Typical range \u00a323,854-\u00a361,471","Honest note: this is almost always seasonal supplementary income for qualified, working teachers during the exam marking period, not a standalone full-time career","Qualifications: must normally be a qualified, currently or recently practising teacher in the relevant subject \u2192 exam boards (AQA, Edexcel, OCR) provide training and standardisation before marking begins"],"u":"https://en.wikipedia.org/wiki/Standardized_test"},{"t":"Educational Psychologist","s":"","c":"Education","k":46,"d":["Trainee \u00a323,000-\u00a333,000 \u2192 newly qualified from \u00a337,000 \u2192 average around \u00a346,142 \u2192 Senior/Principal \u00a350,000-\u00a385,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Psychology helps) \u2192 Psychology degree \u2192 further Master\u2019s/Doctorate in Educational Psychology \u2192 works with children facing barriers to learning like anxiety, bullying or special educational needs"],"u":"https://en.wikipedia.org/wiki/Educational_psychology"},{"t":"School Business Manager","s":"","c":"Education","k":35,"d":["Average around \u00a335,112","Runs the non-teaching side of a school - budgets, HR, facilities, procurement - freeing up headteachers to focus on education","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 degree not always required, relevant business/finance experience often matters more \u2192 School Business Management qualifications (e.g. CSBM) add real value while working"],"u":"https://en.wikipedia.org/wiki/School_business_manager"},{"t":"Solicitor","s":"","c":"Law & Finance","k":56,"d":["Starts around \u00a341,520, City/corporate firms pay significantly more","Experienced solicitors average around \u00a356,000, partners much higher","Qualifications: GCSEs \u2192 A-Levels \u2192 Law degree (3 years) or any degree + law conversion course \u2192 Solicitors Qualifying Exam (SQE) \u2192 2 years qualifying work experience"],"u":"https://en.wikipedia.org/wiki/Solicitor"},{"t":"Barrister","s":"","c":"Law & Finance","k":65,"d":["Self-employed, pays chambers rent (15-25% of fees earned)","Pupillage (training year) minimum \u00a321,060-\u00a323,078, top commercial sets pay \u00a370,000-\u00a385,000","Newly qualified \u00a340,000-\u00a370,000","Mid-career \u00a350,000-\u00a3200,000","Senior/KC (King\u2019s Counsel) can reach \u00a3250,000-\u00a31,000,000+ at the very top","Qualifications: GCSEs \u2192 A-Levels \u2192 Law degree (3 years) or conversion course \u2192 Bar Training Course (costs \u00a318,000-\u00a322,000, paid upfront like Pilot) \u2192 1-year pupillage \u2192 tenancy"],"u":"https://en.wikipedia.org/wiki/Barrister"},{"t":"Chartered Accountant","s":"","c":"Law & Finance","k":70,"d":["Established, experienced chartered accountants typically earn \u00a370,000 or more, and partners and finance directors much more. Starts around \u00a334,000 while training","For comparison, the ONS median for all qualified accountants is about \u00a350,000, and the top quarter earn over about \u00a368,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (often maths/business, though not always required) \u2192 professional qualification (ACA, ACCA or CIMA) studied over 3-4 years while working"],"u":"https://en.wikipedia.org/wiki/Accountant"},{"t": "Accountant", "s": "", "c": "Law & Finance", "k": 50, "d": ["Typical pay for qualified accountants is around £50,000 a year (ONS, 2025). The lowest tenth earn under about £30,000 and the top quarter earn over about £68,000", "Qualifications: GCSEs → A-Levels or an apprenticeship → accounting degree or AAT qualifications, then ACA, ACCA or CIMA while working. You can start as an accounts assistant or trainee with no degree"], "u": "https://en.wikipedia.org/wiki/Accountant", "b": "https://www.ons.gov.uk/employmentandlabourmarket/peopleinwork/earningsandworkinghours/bulletins/annualsurveyofhoursandearnings/latest"},{"t":"Investment Banker","s":"","c":"Law & Finance","k":100,"d":["Entry-level analyst \u00a350,000-\u00a370,000 base, total pay with bonus \u00a384,000-\u00a3165,000","Managing Director level can exceed \u00a3500,000, top performers into seven figures","Qualifications: GCSEs incl. Maths \u2192 A-Levels (top grades needed) \u2192 degree (finance/economics helps, but which university matters enormously for entry) \u2192 extremely competitive graduate scheme, long hours culture is well documented"],"u":"https://en.wikipedia.org/wiki/Investment_banking"},{"t":"Actuary","s":"","c":"Law & Finance","k":70,"d":["Trainee \u00a332,000-\u00a345,000 in London, regional offices 10-20% less","Pay rises in clear, predictable jumps tied to passing professional exams rather than tenure alone","Qualified Fellows earn significantly above the national average, often \u00a370,000-\u00a3100,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels (Maths essential) \u2192 Maths/Actuarial Science/Economics degree \u2192 Institute and Faculty of Actuaries (IFoA) professional exams, usually studied over several years while working, employer typically pays exam fees and study leave"],"u":"https://en.wikipedia.org/wiki/Actuary"},{"t":"Mortgage Broker","s":"","c":"Law & Finance","k":44,"d":["Average around \u00a343,613, low basic salary plus commission (typically 0.35% of mortgage value per case arranged)","Qualifications: GCSEs \u2192 A-Levels \u2192 CeMAP (Certificate in Mortgage Advice and Practice) qualification, achievable in months, not years \u2192 no degree required, genuinely accessible entry into financial services"],"u":"https://en.wikipedia.org/wiki/Mortgage_broker"},{"t":"Tax Advisor","s":"","c":"Law & Finance","k":40,"d":["Average around \u00a336,830-\u00a346,201 depending on source and specialism \u2192 corporate/international tax specialists in large firms considerably higher","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (accounting/law helps) \u2192 ATT (Association of Taxation Technicians) then CTA (Chartered Tax Adviser) qualifications, studied while working over several years"],"u":"https://en.wikipedia.org/wiki/Tax_advisor"},{"t":"Insurance Underwriter","s":"","c":"Law & Finance","k":38,"d":["Average around \u00a338,107, typical range \u00a327,199-\u00a354,029","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 CII (Chartered Insurance Institute) qualifications studied while working add real value \u2192 assesses and prices risk, deciding what insurance a company is willing to cover and at what price"],"u":"https://en.wikipedia.org/wiki/Underwriting"},{"t":"FX/Forex Trader","s":"","c":"Law & Finance","k":90,"d":["Employed at a bank or fund - genuinely different from independent retail trading, which is NOT a salaried career at all","Junior trading analyst \u00a345,000-\u00a370,000 in London \u2192 experienced desk trader \u00a390,000-\u00a3150,000 \u2192 senior traders average \u00a3117,000, top earners exceed \u00a3300,000","Honest warning: independent/retail trading carries no guaranteed income, and FCA data shows 70-80% of retail accounts actually lose money - this is not a realistic backup path to the salaried version","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Finance/Maths/Economics degree \u2192 extremely competitive graduate entry at banks and hedge funds"],"u":"https://en.wikipedia.org/wiki/Foreign_exchange_market"},{"t":"Stockbroker","s":"","c":"Law & Finance","k":44,"d":["Average around \u00a344,219","Buys and sells shares and other securities on behalf of clients, either advising them directly or executing trades \u2192 pay often boosted by commission on client transactions","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (finance/economics helps, not always essential) \u2192 CISI (Chartered Institute for Securities & Investment) qualifications required to give investment advice"],"u":"https://en.wikipedia.org/wiki/Stockbroker"},{"t":"Bullion/Precious Metals Trader","s":"","c":"Law & Finance","k":45,"d":["Entry-level roles at dedicated bullion dealers \u00a330,000-\u00a340,000 \u2192 gold traders and investment advisors at private banks/wealth managers can exceed \u00a3200,000 plus bonus or revenue share, some work commission-only","Genuinely wide range depending on employer - a high street bullion dealer vs. a City trading desk are very different jobs with the same job title","Qualifications: no fixed route - GCSEs sufficient for entry-level dealer roles, while trading-desk positions typically require a finance/quantitative degree"],"u":"https://en.wikipedia.org/wiki/Bullion"},{"t":"Independent Financial Advisor","s":"IFA","c":"Law & Finance","k":53,"d":["Trainee \u00a322,000-\u00a330,000 \u2192 qualified \u00a330,000-\u00a353,000 \u2192 senior/Chartered Financial Planner \u00a360,000-\u00a380,000+ \u2192 an established self-employed IFA with a strong client book can exceed \u00a3100,000-\u00a3150,000, with genuinely no fixed ceiling","Qualifications: GCSEs \u2192 A-Levels \u2192 Level 4 Diploma in Financial Planning (CII or CISI) is the regulatory minimum to give advice \u2192 Chartered status (Level 6) significantly boosts client trust and fee rates"],"u":"https://en.wikipedia.org/wiki/Financial_adviser"},{"t":"Notary Public","s":"","c":"Law & Finance","k":41,"d":["Honest reality: in England and Wales this is almost never a standalone job - very few people work solely as a notary, since most are already qualified solicitors, and notarial work typically adds just \u00a33,000-\u00a320,000 on top of their existing solicitor income","Prepares and witnesses documents for use abroad, and handles overseas property and immigration paperwork","Qualifications: qualified Solicitor (see that entry elsewhere in this guide) \u2192 further Notarial Practice Course via the Faculty Office \u2192 a genuinely rare, specialist add-on qualification rather than a career path in itself"],"u":"https://en.wikipedia.org/wiki/Notary_public_(England_and_Wales)"},{"t":"Credit Controller","s":"","c":"Law & Finance","k":27,"d":["Average around \u00a326,000-\u00a327,000, typical range \u00a323,000-\u00a333,000 \u2192 Senior Credit Controller/Credit Manager considerably higher","Chases outstanding invoices and manages a company\u2019s cash flow by ensuring customers pay on time","Qualifications: GCSEs \u2192 A-Levels not always required \u2192 no degree needed to start \u2192 CICM (Chartered Institute of Credit Management) qualifications studied while working add genuine progression toward Credit Manager"],"u":"https://en.wikipedia.org/wiki/Credit_control"},{"t":"Insolvency Practitioner","s":"IP","c":"Law & Finance","k":55,"d":["Analyst/Assistant Manager \u00a335,000-\u00a355,000 \u2192 among the highest-paid specialists in accounting once fully licensed \u2192 senior IPs at large firms considerably higher","Genuinely counter-cyclical work - demand rises during economic downturns as company and personal insolvencies increase, unlike most careers here","Qualifications: ACCA/CIMA accounting qualification as the foundation \u2192 JIEB (Joint Insolvency Examination Board) exams \u2192 IP licence required to formally manage administrations, liquidations and bankruptcies"],"u":"https://en.wikipedia.org/wiki/Insolvency_practitioner"},{"t":"Tax Inspector","s":"HMRC","c":"Law & Finance","k":40,"d":["HMRC Graduate Tax Specialist Programme starts \u00a337,682 (\u00a342,631 in London) \u2192 guaranteed promotion to a minimum of \u00a358,541 (\u00a365,869 London) on qualifying \u2192 Grade 7 tax officers can rise further with experience","Genuinely open route: over 40% of successful internal candidates in a recent campaign had no degree","Qualifications: GCSEs \u2192 2:2 degree or equivalent, OR no degree needed for existing civil servants \u2192 3-4 year Tax Specialist Programme combining real casework with study \u2192 investigates fraud, negotiates disputed tax and audits complex accounts"],"u":"https://en.wikipedia.org/wiki/HM_Revenue_and_Customs"},{"t":"Financial Analyst","s":"","c":"Law & Finance","k":40,"d":["Junior entry \u00a318,000-\u00a335,000, average around \u00a324,700-\u00a328,400 \u2192 experienced analysts in financial services specifically \u00a349,500-\u00a361,750","Evaluates financial data to help organisations and investors make better decisions - budgeting, forecasting, financial modelling and performance reporting","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (finance/economics/maths helps, not always required) \u2192 ACCA, CIMA or ACA professional qualifications, studied while working, significantly boost pay and progression"],"u":"https://en.wikipedia.org/wiki/Financial_analyst"},{"t":"Pension Consultant","s":"","c":"Law & Finance","k":55,"d":["A genuinely clean career ladder: Pensions Administrator \u00a323,000-\u00a330,000 \u2192 Senior Administrator \u00a330,000-\u00a340,000 \u2192 Consultant \u00a345,000-\u00a365,000 \u2192 Senior Consultant up to \u00a390,000 \u2192 Director/Partner at a major firm exceeding \u00a3180,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 PMI (Pensions Management Institute) qualifications studied while working are the standard route to consultant level"],"u":"https://en.wikipedia.org/wiki/Pension"},{"t":"Paralegal","s":"","c":"Law & Finance","k":28,"d":["Junior \u00a324,500-\u00a327,000 \u2192 mid-level \u00a327,000-\u00a334,000 \u2192 senior/specialist with file ownership \u00a332,000-\u00a338,000+, London considerably higher \u2192 Chartered (CILEX) senior paralegals can reach \u00a345,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 Paralegal work counts as qualifying experience toward the SQE, a genuinely valuable stepping stone toward becoming a Solicitor without needing a law degree first"],"u":"https://en.wikipedia.org/wiki/Paralegal"},{"t":"Insurance Broker","s":"","c":"Law & Finance","k":35,"d":["Average around \u00a332,600-\u00a337,300, London higher around \u00a347,400","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 Chartered Insurance Institute (CII) qualifications add real value and are often studied while working"],"u":"https://en.wikipedia.org/wiki/Insurance_broker"},{"t":"Software Developer/Engineer","s":"","c":"Technology","k":65,"d":["Starts around \u00a328,000-\u00a335,000","Experienced developers average around \u00a365,000, senior/specialist roles \u00a380,000-\u00a3100,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a coding bootcamp/apprenticeship route \u2192 Computer Science degree (3 years) OR self-taught/apprenticeship path is increasingly common and valid"],"u":"https://en.wikipedia.org/wiki/Software_developer"},{"t":"Data Scientist","s":"","c":"Technology","k":55,"d":["Starts around \u00a335,000","Typical range \u00a335,000-\u00a395,000 depending on sector and specialism (AI/ML skills command a premium)","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 degree in Maths, Computer Science, Statistics or similar (3 years), often followed by a Master\u2019s for the strongest roles"],"u":"https://en.wikipedia.org/wiki/Data_science"},{"t":"Web Developer","s":"","c":"Technology","k":45,"d":["Junior \u00a325,000-\u00a338,000","Mid-level \u00a338,000-\u00a355,000","Senior \u00a355,000-\u00a378,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a coding bootcamp \u2192 Computer Science degree OR bootcamp graduates often start slightly lower but the gap closes within 2-3 years for strong performers with a good portfolio"],"u":"https://en.wikipedia.org/wiki/Web_developer"},{"t":"Cybersecurity Analyst","s":"","c":"Technology","k":48,"d":["Entry-level \u00a330,000-\u00a340,000 \u2192 average around \u00a348,877 \u2192 senior/architect roles \u00a396,000-\u00a3110,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Computer Science/Cybersecurity degree or apprenticeship route \u2192 certifications like CompTIA Security+ or CISSP add real value \u2192 many start in general IT support before specialising"],"u":"https://en.wikipedia.org/wiki/Computer_security"},{"t":"IT Support Technician","s":"","c":"Technology","k":29,"d":["Average around \u00a329,469-\u00a330,124, London higher around \u00a334,067","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a Level 3 IT apprenticeship (no degree needed) \u2192 a genuinely common and accessible entry point into the wider tech sector, many progress into cybersecurity, networking or development from here"],"u":"https://en.wikipedia.org/wiki/Technical_support"},{"t":"Network Engineer","s":"","c":"Technology","k":42,"d":["Average around \u00a338,174-\u00a345,041","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a Level 3/4 apprenticeship (no degree needed) \u2192 Cisco/CCNA certifications add real, recognised value \u2192 designs, builds and maintains the networks that keep organisations connected, increasingly focused on hybrid cloud environments"],"u":"https://en.wikipedia.org/wiki/Network_administrator"},{"t":"Software QA Tester","s":"","c":"Technology","k":35,"d":["Manual testers average \u00a325,678-\u00a331,872 \u2192 automation-focused QA Engineers \u00a352,000-\u00a358,000, senior \u00a390,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a Level 4 apprenticeship (no degree needed) \u2192 learning automation tools (Selenium, Playwright) and basic coding is what separates average pay from the highest earners in this field"],"u":"https://en.wikipedia.org/wiki/Software_testing"},{"t":"DevOps/Cloud Engineer","s":"","c":"Technology","k":60,"d":["Entry-level \u00a331,470-\u00a340,000 \u2192 mid-career \u00a351,520-\u00a358,818 \u2192 senior (10-20 years) \u00a383,650-\u00a395,000+, London commanding a real premium \u2192 AWS/Azure certifications add \u00a35,000-\u00a315,000 to salary","One of the highest-compensated, most in-demand tech roles in the UK right now, bridging software development and IT operations","Qualifications: GCSEs incl. Maths \u2192 A-Levels or apprenticeship route \u2192 Computer Science degree helps but many transition from sysadmin or general IT support backgrounds instead"],"u":"https://en.wikipedia.org/wiki/DevOps"},{"t":"AI/Machine Learning Engineer","s":"","c":"Technology","k":75,"d":["Median around \u00a367,000-\u00a375,000 depending on source \u2192 London specifically \u00a376,000, senior/lead roles \u00a3120,000-\u00a3190,000+","One of the fastest-growing, most sought-after tech specialisms as AI adoption accelerates across every industry","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Computer Science/Maths/Statistics degree, often a Master\u2019s or PhD for research-focused roles \u2192 strong Python and statistics skills are the practical foundation employers actually test for"],"u":"https://en.wikipedia.org/wiki/Machine_learning"},{"t":"UX Researcher","s":"User Experience","c":"Technology","k":53,"d":["Average around \u00a353,000-\u00a354,500, typical range \u00a337,000-\u00a366,000+ depending on seniority and company","Studies how real people actually use products and services, feeding findings back into design decisions","Qualifications: GCSEs \u2192 A-Levels \u2192 Psychology/HCI/Design degree helps but isn\u2019t always essential \u2192 many transition from psychology, market research or design backgrounds instead of a dedicated UX degree"],"u":"https://en.wikipedia.org/wiki/User_experience"},{"t":"Sports Performance Analyst","s":"","c":"Technology","k":33,"d":["Breaks down match footage, GPS tracking and statistics to inform coaching decisions, distinct from the on-pitch coaching roles elsewhere in this guide","Typical range \u00a325,000-\u00a350,000+, senior analysts at top-flight clubs and national governing bodies towards the upper end","Qualifications: GCSEs \u2192 A-Levels \u2192 Sports Science/Performance Analysis degree helps, though strong data and video-analysis software skills (Hudl, Opta) matter as much as the degree itself \u2192 a genuinely fast-growing role as data becomes more central to elite sport"],"u":"https://en.wikipedia.org/wiki/Performance_analysis_(sports)"},{"t":"Video Game Developer/Programmer","s":"","c":"Technology","k":42,"d":["Entry-level \u00a322,000-\u00a327,000 \u2192 median around \u00a336,000-\u00a350,000 \u2192 senior/experienced \u00a354,000-\u00a376,000+","A genuinely fast-growing global industry, UK games market alone worth billions and still expanding","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Computer Science/Games Development degree helps, though a strong self-built portfolio can substitute for formal qualifications \u2192 specialising (engine programming, graphics, AI) boosts pay considerably"],"u":"https://en.wikipedia.org/wiki/Video_game_developer"},{"t":"Blockchain Developer","s":"","c":"Technology","k":100,"d":["25th-75th percentile \u00a385,000-\u00a3130,000, median around \u00a3100,000 - genuinely one of the highest-paid entry points in tech given how few developers hold this specialist skill","Builds decentralised applications and smart contracts, used across finance, supply chain and increasingly wider industry","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Computer Science degree helps, though many blockchain-specific skills are self-taught or learned via specialist bootcamps \u2192 a genuinely niche, fast-evolving field where practical project experience counts for more than formal credentials"],"u":"https://en.wikipedia.org/wiki/Blockchain"},{"t":"Robotics Engineer","s":"","c":"Technology","k":48,"d":["Starting salary around \u00a325,500 \u2192 average around \u00a340,000-\u00a355,000 \u2192 senior/specialist roles can exceed \u00a390,000","Designs, builds and programmes robots and automated systems used in manufacturing, healthcare, logistics and beyond","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Robotics/Mechatronics/Electrical Engineering degree \u2192 a genuinely growing field as automation expands across UK industry"],"u":"https://en.wikipedia.org/wiki/Robotics_engineer"},{"t":"Odds Compiler/Sports Trader","s":"gambling industry","c":"Technology","k":33,"d":["Average around \u00a327,000-\u00a340,000, typically \u00a333,000","Sets and adjusts betting odds in real time using statistical models, sports knowledge and market awareness \u2192 junior traders focus on odds compilation, senior traders take on risk management","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 degree helps (maths/statistics) but not always required \u2192 strong numeracy and quick decision-making under pressure matter more than formal qualifications"],"u":"https://en.wikipedia.org/wiki/Odds_compiler"},{"t":"Drone Pilot/UAV Operator","s":"","c":"Technology","k":38,"d":["Average around \u00a331,000-\u00a341,000, London higher around \u00a352,000 \u2192 senior/specialist BVLOS (beyond visual line of sight) operators can exceed \u00a3100,000","A genuinely fast-growing UK field, estimated 3,000-6,000 specialist roles, growing 15-25% a year as regulations expand what drones are allowed to do","Qualifications: no degree needed \u2192 CAA-approved drone pilot qualification (achievable in weeks, not years) \u2192 used in surveying, agriculture, filming, inspection and emergency services"],"u":"https://en.wikipedia.org/wiki/Unmanned_aerial_vehicle"},{"t":"Meteorologist","s":"Met Office","c":"Technology","k":40,"d":["Foundation operational meteorologist \u00a326,000-\u00a329,000 \u2192 average around \u00a333,000-\u00a340,000 \u2192 chief forecasters/experts up to \u00a366,000","12-hour shifts covering days, nights and weekends are standard, since forecasts run around the clock","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels (Maths, Physics) \u2192 Meteorology/physical science/maths degree \u2192 analyses satellite, radar and computer model data to forecast weather for aviation, farming, shipping and the public"],"u":"https://en.wikipedia.org/wiki/Meteorologist"},{"t":"Volcanologist","s":"","c":"Technology","k":35,"d":["Honest reality: since the UK has no active volcanoes, this is almost entirely an academic research career studying international volcanic samples in a university lab, not fieldwork on active eruptions","Postdoctoral research associate roles \u00a332,000-\u00a337,000","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Chemistry, Physics, Geography) \u2192 Geology/Earth Sciences degree \u2192 PhD in Volcanology essentially required \u2192 a genuinely rare, niche specialism with very few permanent UK posts available at any time"],"u":"https://en.wikipedia.org/wiki/Volcanology"},{"t":"Data Analyst","s":"","c":"Technology","k":36,"d":["Entry-level \u00a323,000-\u00a325,000 \u2192 average around \u00a335,000-\u00a338,000 \u2192 London \u00a340,000-\u00a350,000, experienced \u00a360,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels or a Level 4 apprenticeship (a degree is not always required - practical skills in SQL and data tools matter more) \u2192 a common stepping stone toward Data Scientist roles"],"u":"https://en.wikipedia.org/wiki/Data_analysis"},{"t":"Product Manager","s":"","c":"Technology","k":63,"d":["Entry-level Associate PM \u00a327,500-\u00a332,000 \u2192 average around \u00a363,000, London \u00a369,519 \u2192 Head of Product at a funded scale-up can clear \u00a3180,000 with bonus/equity","Qualifications: no single fixed route - many transition from analyst, delivery or engineering roles rather than a dedicated degree \u2192 one of the widest-banded roles in tech, seniority and company stage matter more than title alone"],"u":"https://en.wikipedia.org/wiki/Product_manager"},{"t":"UX/UI Designer","s":"","c":"Technology","k":48,"d":["Entry-level \u00a324,000-\u00a338,000 \u2192 median around \u00a355,000, national average roughly \u00a348,000 \u2192 senior/principal level \u00a3130,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 Design/HCI degree (not always required) \u2192 a strong portfolio matters more than years of experience - one solid year of relevant work can outweigh three weak ones"],"u":"https://en.wikipedia.org/wiki/User_experience_design"},{"t":"Estate Agent","s":"","c":"Business","k":35,"d":["Junior negotiator basic \u00a316,000-\u00a322,000 plus commission (on-target earnings \u00a325,000-\u00a340,000)","Senior negotiator/lister OTE \u00a350,000-\u00a370,000 in busy markets","Branch Manager OTE \u00a365,000 outside London, \u00a388,000 in inner London","Qualifications: no specific qualifications required - GCSEs are enough, communication and sales skills matter most, many enter straight from school"],"u":"https://en.wikipedia.org/wiki/Estate_agent"},{"t":"Auctioneer","s":"","c":"Business","k":34,"d":["Average around \u00a333,971, typical range \u00a330,614-\u00a338,514","Property auctioneers commonly work on commission (around 2% + VAT of sale price), only paid when a lot actually sells \u2192 fine art/antiques auctioneers at major houses can earn considerably more through reputation and specialism","Qualifications: no formal qualifications required - GCSEs sufficient, though A-Levels help \u2192 usually builds up through porter/cataloguer roles at an auction house before conducting sales"],"u":"https://en.wikipedia.org/wiki/Auctioneer"},{"t":"Sports/Football Agent","s":"","c":"Business","k":32,"d":["Average around \u00a329,000-\u00a332,000 base, typical range \u00a322,000-\u00a338,000 \u2192 genuinely enormous variance depending on client roster - senior/established agents representing top-flight players can reach \u00a370,000-\u00a3150,000+, almost entirely commission-driven on client contracts and transfers","Qualifications: no fixed degree route \u2192 FA-regulated intermediary registration required to legally represent players \u2192 building a client roster from grassroots/academy level upward is the realistic starting point, not signing a star player straight away"],"u":"https://en.wikipedia.org/wiki/Sports_agent"},{"t":"Retail/Store Manager","s":"","c":"Business","k":33,"d":["Average around \u00a331,000-\u00a334,000","Experienced/senior managers \u00a348,000-\u00a354,000, especially in London","Qualifications: no specific qualifications required - GCSEs are enough, usually builds up via retail assistant/supervisor roles first \u2192 genuinely accessible entry point into management without a degree"],"u":"https://en.wikipedia.org/wiki/Retail"},{"t":"Marketing Manager","s":"","c":"Business","k":45,"d":["Junior \u00a325,000-\u00a332,000","Typical range \u00a340,000-\u00a350,000","Senior managers \u00a355,000-\u00a370,000, Marketing Directors \u00a385,000-\u00a3130,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (marketing/business helps but not always required) \u2192 usually builds up via Marketing Executive/Coordinator roles first \u2192 a CIM qualification or MBA can boost pay"],"u":"https://en.wikipedia.org/wiki/Marketing_management"},{"t":"HR Manager","s":"","c":"Business","k":45,"d":["Typical range \u00a340,000-\u00a355,000, London/large organisations \u00a350,000-\u00a365,000","HR Directors \u00a370,000-\u00a3130,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (not always required) \u2192 CIPD Level 3, 5 or 7 professional qualifications studied while working, each level adding real salary premium"],"u":"https://en.wikipedia.org/wiki/Human_resource_management"},{"t":"Project Manager","s":"","c":"Business","k":52,"d":["Junior/coordinator roles \u00a327,000-\u00a338,000 (a common paid entry point, no need to start as a full PM)","Typical range \u00a345,000-\u00a365,000","Senior PMs \u00a360,000-\u00a380,000, Programme Directors \u00a390,000-\u00a3145,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (any subject) or apprenticeship route \u2192 PRINCE2 or APM/PMP certifications add a real salary premium"],"u":"https://en.wikipedia.org/wiki/Project_manager"},{"t":"Supply Chain Manager","s":"","c":"Business","k":42,"d":["Average around \u00a340,500-\u00a344,700","Typical range \u00a328,000-\u00a362,000 depending on company size and sector","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (logistics/business helps but not always required) \u2192 CIPS or CILT professional qualifications add real value \u2192 usually builds up via coordinator/analyst roles first"],"u":"https://en.wikipedia.org/wiki/Supply_chain_management"},{"t":"Recruitment Consultant","s":"","c":"Business","k":32,"d":["Average around \u00a332,451, London around \u00a342,336","Low basic salary is common, with commission often forming a significant part of total earnings for successful consultants","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not required \u2192 a genuinely accessible entry point into business, success depends heavily on sales ability rather than qualifications"],"u":"https://en.wikipedia.org/wiki/Recruitment"},{"t":"Business Analyst","s":"","c":"Business","k":48,"d":["Entry-level \u00a324,000-\u00a333,000 \u2192 average around \u00a348,000 \u2192 senior/lead (8+ years) \u00a380,000-\u00a3110,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (business/analytical subjects help, not always essential) \u2192 BCS/IIBA business analysis certifications add real value while working"],"u":"https://en.wikipedia.org/wiki/Business_analyst"},{"t":"Compliance Officer","s":"","c":"Business","k":36,"d":["National average \u00a335,000-\u00a336,000, London around \u00a343,327 \u2192 experienced officers \u00a345,000-\u00a365,000, senior in financial services \u00a350,000-\u00a385,000+ \u2192 Chief Compliance Officers at banks can exceed \u00a3300,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (law/business/finance helps) \u2192 ICA or CISI certifications add real value \u2192 a genuinely secure career path since regulatory demand doesn\u2019t disappear in a downturn"],"u":"https://en.wikipedia.org/wiki/Regulatory_compliance"},{"t":"Public Relations/Communications Manager","s":"PR","c":"Business","k":50,"d":["Genuinely clear career ladder: assistant/trainee \u00a318,000-\u00a322,000 \u2192 officer \u00a325,000-\u00a337,000 \u2192 manager \u00a342,000-\u00a360,000 \u2192 head of communications \u00a358,000-\u00a366,000 \u2192 director/senior leadership averaging \u00a391,828","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (PR/journalism/communications helps, not always essential) \u2192 CIPR or PRCA qualifications add value \u2192 crisis management and media relations experience genuinely boosts pay"],"u":"https://en.wikipedia.org/wiki/Public_relations"},{"t":"Translator/Interpreter","s":"","c":"Business","k":36,"d":["Average around \u00a330,700-\u00a336,231, typical range \u00a325,700-\u00a356,500 \u2192 top earners (specialist legal/medical/conference interpreters, private market work) can exceed \u00a398,800","Qualifications: fluency in at least one second language essential, plus excellent English writing skills \u2192 no degree strictly required, though a language degree helps \u2192 Chartered Institute of Linguists or Institute of Translation and Interpreting qualifications add real professional credibility \u2192 enhanced background checks needed for national security-related work"],"u":"https://en.wikipedia.org/wiki/Translation"},{"t":"Procurement Manager","s":"","c":"Business","k":40,"d":["Procurement Officer entry \u00a320,000-\u00a345,000 \u2192 Manager level considerably higher, senior/Chief Procurement Officer roles at large organisations well into six figures","Negotiates contracts and manages supplier relationships to secure the best value for an organisation\u2019s purchasing","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 CIPS (Chartered Institute of Procurement & Supply) qualifications, studied while working, add genuine value and career progression"],"u":"https://en.wikipedia.org/wiki/Procurement"},{"t":"Private Estate Manager","s":"","c":"Business","k":70,"d":["Oversees the complete operations of a high-net-worth individual\u2019s property or properties, not agricultural/rural land management","Entry-level \u00a345,000-\u00a360,000 \u2192 experienced \u00a360,000-\u00a380,000 \u2192 senior estate managers command \u00a380,000-\u00a3120,000+, London and the South East 15-25% higher still","Genuinely substantial benefits often included on top of salary - live-in accommodation worth \u00a315,000-\u00a330,000, a car, and other perks adding 20-30% to the base package","Qualifications: no fixed degree route \u2192 extensive experience in hospitality, property management or luxury service required \u2192 coordinates household staff, security and maintenance for property owners or family offices"],"u":"https://en.wikipedia.org/wiki/Estate_(house)"},{"t":"GP Practice Manager","s":"","c":"Business","k":44,"d":["Runs the business/administrative side of a doctor\u2019s surgery, distinct from the clinical roles elsewhere in this guide","Average around \u00a341,000-\u00a349,000, typical range \u00a330,000-\u00a360,000 \u2192 genuinely wide variation, from under \u00a320,000 to over \u00a3100,000, since pay is set directly by GP partners rather than a standardised NHS scale","Responsible for finance, HR, IT and day-to-day running of the practice, working closely with the GP partners","Qualifications: no degree required \u2192 usually builds up through medical secretary/admin roles \u2192 a leadership or management qualification (e.g. AMSPAR) genuinely strengthens promotion prospects"],"u":"https://en.wikipedia.org/wiki/General_practitioner"},{"t":"Royal Household Butler/Household Staff","s":"with a room and full board included","c":"Business","k":40,"d":["A genuinely striking range depending on employer: a trainee butler at Buckingham Palace starts around \u00a315,000-\u00a329,000 \u2192 a highly experienced private-sector butler for an ultra-high-net-worth family can earn \u00a360,000-\u00a3130,000+","The Royal Household also employs communications, HR, engineering and digital staff on ordinary market-rate salaries alongside traditional roles like footmen and housekeepers","Qualifications: no fixed degree route \u2192 formal butler/silver-service training \u2192 discretion, precision and years of experience in high-standard households matter more than any qualification"],"u":"https://en.wikipedia.org/wiki/Royal_Household"},{"t":"Operations Manager","s":"","c":"Business","k":41,"d":["Average around \u00a340,500-\u00a344,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (business helps but not always required) \u2192 usually builds up through supervisory/team leader roles first \u2192 responsible for day-to-day running of a company or department, including staffing decisions"],"u":"https://en.wikipedia.org/wiki/Operations_management"},{"t":"Car Sales Executive","s":"retail","c":"Business","k":32,"d":["Basic salary typically just \u00a320,000-\u00a325,000, with on-target earnings (OTE) including commission averaging around \u00a349,000-\u00a350,000 \u2192 top performers can reach \u00a396,000","Qualifications: no degree needed - GCSEs sufficient, sales ability matters far more than qualifications \u2192 a genuinely common entry point into a wider sales career, often the first rung toward management"],"u":"https://en.wikipedia.org/wiki/Car_dealership"},{"t":"Pharmaceutical Sales Representative","s":"","c":"Business","k":49,"d":["Graduate starting salary closer to \u00a324,000 \u2192 typical range \u00a340,000-\u00a360,000 once established \u2192 London higher, up to \u00a375,770","Qualifications: GCSEs \u2192 A-Levels \u2192 life sciences degree genuinely helps given the scientific knowledge required to discuss drugs with doctors \u2192 pay often boosted significantly by performance-related bonuses on top of base salary"],"u":"https://en.wikipedia.org/wiki/Pharmaceutical_sales_representative"},{"t":"Chief Executive Officer","s":"CEO","c":"Business","k":150,"d":["The top of the sales-to-management ladder shown across this Career Guide","Typical UK SME CEO \u00a390,000-\u00a3250,000+ depending on company size and location \u2192 London CEOs average around \u00a3386,000","Honest reality check: FTSE 100 CEO median total pay is a staggering \u00a34.58 million - but that reflects perhaps 100 people in the entire country, not a realistic target for the vast majority who reach this level","Qualifications: no single fixed route - typically 15-20+ years building through management roles, an MBA can help at the largest companies but leadership track record matters more than any qualification"],"u":"https://en.wikipedia.org/wiki/Chief_executive_officer"},{"t":"Betting Shop Manager","s":"bookmaking/gambling industry","c":"Business","k":27,"d":["Trainee \u00a313,500-\u00a315,500 \u2192 manager \u00a320,000-\u00a330,000, London slightly higher around \u00a327,549 \u2192 area manager covering ~100 shops can earn \u00a345,000+ plus bonuses","Qualifications: GCSEs incl. Maths \u2192 no degree required \u2192 often starts as a cashier, working up through supervisor to manager \u2192 basic maths test for odds/percentages usually required at interview"],"u":"https://en.wikipedia.org/wiki/Bookmaker"},{"t":"Charity Fundraiser","s":"","c":"Business","k":23,"d":["Average around \u00a323,196, typical range \u00a318,000-\u00a335,000 \u2192 Director of Fundraising at a large charity considerably higher","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 builds donor relationships and designs campaigns \u2192 genuinely meaningful work, though pay is modest relative to equivalent commercial sales/marketing roles"],"u":"https://en.wikipedia.org/wiki/Fundraising"},{"t":"Retail/Branch Bank Manager","s":"","c":"Business","k":37,"d":["Distinct from Investment Banker elsewhere in this guide - runs a high street branch rather than working in corporate finance","Average around \u00a336,000-\u00a339,000, London slightly higher \u2192 typical range \u00a328,000-\u00a381,000 for senior/regional roles","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 usually builds up through cashier and supervisory roles first \u2192 a genuinely realistic, accessible route into financial services management without needing the elite graduate scheme entry that investment banking requires"],"u":"https://en.wikipedia.org/wiki/Bank_manager"},{"t":"Charity CEO","s":"","c":"Business","k":190,"d":["Distinct from Charity Fundraiser and the general CEO entry elsewhere in this guide","A genuinely enormous real range depending on charity size: Arts Council England\u2019s chief earns \u00a340,000, while most major UK charity CEOs (Age UK, Cancer Research UK, NSPCC, British Red Cross) cluster around \u00a3120,000-\u00a3240,000 \u2192 a handful at very large health/social care charities exceed \u00a3400,000-\u00a31,200,000","Qualifications: no single fixed route - typically 15-20+ years building through charity sector management \u2192 genuinely public, scrutinised pay given charities\u2019 reliance on donations"],"u":"https://en.wikipedia.org/wiki/Charitable_organization"},{"t":"Architect","s":"","c":"Engineering & Design","k":42,"d":["Part 1 assistants earn \u00a322,000-\u00a328,000","Newly qualified (Part 3) \u00a335,000-\u00a346,000","Senior architects \u00a345,000-\u00a365,000","Directors/partners \u00a370,000-\u00a3130,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 7 years total: 3-year Part 1 degree + 2-year Part 2 postgraduate diploma/MArch + 2 years practical training \u2192 Part 3 exam \u2192 register with the Architects Registration Board (legally required to use the title \u201carchitect\u201d)"],"u":"https://en.wikipedia.org/wiki/Architect"},{"t":"Civil Engineer","s":"","c":"Engineering & Design","k":55,"d":["Entry level (1-3 years) around \u00a342,614","Senior (8+ years) \u00a368,104","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels (Maths, Physics) \u2192 Civil Engineering degree (3-4 years) \u2192 Chartered Engineer (CEng) status via the Institution of Civil Engineers, typically several more years of work experience"],"u":"https://en.wikipedia.org/wiki/Civil_engineer"},{"t":"Quantity Surveyor","s":"","c":"Engineering & Design","k":50,"d":["Graduate \u00a325,000-\u00a332,000","Chartered (MRICS) \u00a344,500-\u00a356,000","Senior/management \u00a357,000-\u00a371,000+","Qualifications: GCSEs incl. Maths \u2192 A-Levels \u2192 Quantity Surveying/Construction degree (3-4 years) \u2192 Chartered status via the Royal Institution of Chartered Surveyors (RICS), a real and significant salary premium"],"u":"https://en.wikipedia.org/wiki/Quantity_surveyor"},{"t":"Building Surveyor","s":"","c":"Engineering & Design","k":52,"d":["Average range \u00a345,000-\u00a360,000","Graduate Surveyor \u2192 Surveyor \u2192 Senior Surveyor \u2192 Associate Director \u2192 Director career ladder, with senior leadership able to exceed \u00a3100,000","Qualifications: GCSEs \u2192 A-Levels \u2192 Building Surveying degree (3-4 years) \u2192 MRICS Chartered status via the Royal Institution of Chartered Surveyors is widely seen as one of the biggest single boosts to pay in the whole profession"],"u":"https://en.wikipedia.org/wiki/Building_surveying"},{"t":"Land Surveyor","s":"","c":"Engineering & Design","k":35,"d":["Distinct from Building/Quantity Surveyor elsewhere in this guide - measures and maps land and construction sites rather than inspecting buildings or costing projects","Average around \u00a334,867, typical range \u00a325,420-\u00a350,932","Qualifications: GCSEs \u2192 A-Levels \u2192 Geomatics/Land Surveying degree (or a related degree plus training) \u2192 MRICS Chartered status via RICS adds a real premium, same as other surveying disciplines"],"u":"https://en.wikipedia.org/wiki/Surveying"},{"t":"Cartographer","s":"","c":"Engineering & Design","k":27,"d":["Distinct from Land Surveyor elsewhere in this guide - creates and maintains the finished maps rather than measuring the land itself","Starting \u00a318,000-\u00a322,000 \u2192 experienced \u00a320,000-\u00a330,000 \u2192 senior \u00a330,000-\u00a347,000","A genuinely small, close-knit profession where word of mouth matters - employers range from Ordnance Survey to the British Antarctic Survey, the RAF (as air cartographers) and the British Army (as geographic technicians)","Qualifications: no degree required \u2192 Level 3 Geospatial Survey Technician apprenticeship straight from school, or a GIS/Geography degree route \u2192 strong GIS software skills and a real eye for design both matter"],"u":"https://en.wikipedia.org/wiki/Cartography"},{"t":"Town/Urban Planner","s":"","c":"Engineering & Design","k":32,"d":["Average around \u00a326,275-\u00a332,406, typical range \u00a321,000-\u00a350,000","Oversees community development decisions - housing, transport, environmental impact - and processes planning applications and zoning requests","Qualifications: GCSEs \u2192 A-Levels \u2192 RTPI-accredited Town Planning degree (or a related degree plus postgraduate conversion) \u2192 Chartered status via the Royal Town Planning Institute (RTPI) adds a real premium"],"u":"https://en.wikipedia.org/wiki/Urban_planner"},{"t":"Landscape Architect","s":"","c":"Engineering & Design","k":37,"d":["Entry-level around \u00a323,710 \u2192 average around \u00a337,584 \u2192 typical range \u00a327,551-\u00a351,269","Qualifications: GCSEs \u2192 A-Levels \u2192 Landscape Architecture degree (accredited by the Landscape Institute) \u2192 CMLI Chartered status via the Landscape Institute significantly boosts senior earning potential"],"u":"https://en.wikipedia.org/wiki/Landscape_architecture"},{"t":"Petroleum Engineer","s":"","c":"Engineering & Design","k":60,"d":["Genuinely one of the highest-paid engineering disciplines - graduate schemes around \u00a328,000-\u00a340,000 \u2192 average \u00a354,000-\u00a360,000 \u2192 median around \u00a391,375 \u2192 top experienced engineers exceed \u00a3136,000-\u00a3164,000","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Petroleum/Chemical Engineering degree \u2192 Aberdeen is the UK\u2019s hub for this industry, though offshore/North Sea roles pay a real premium over office-based positions"],"u":"https://en.wikipedia.org/wiki/Petroleum_engineering"},{"t":"Petrochemical Engineer","s":"","c":"Engineering & Design","k":50,"d":["Distinct from Petroleum Engineer elsewhere in this guide - focused on chemical plants and refining rather than oil extraction specifically","Entry-level \u00a330,000-\u00a342,494 \u2192 average \u00a355,000-\u00a360,275 \u2192 senior (8+ years) \u00a368,714-\u00a390,000+","Qualifications: GCSEs incl. Maths and Chemistry \u2192 A-Levels \u2192 Chemical Engineering degree \u2192 designs the processes and equipment that turn raw materials into products like plastics, fuels and detergents"],"u":"https://en.wikipedia.org/wiki/Chemical_engineering"},{"t":"Mining Engineer","s":"","c":"Engineering & Design","k":45,"d":["Honest reality: due to the decline of large-scale UK mining, most roles are now genuinely international, with opportunities and pay considerably stronger overseas","UK starting salary \u00a325,000-\u00a335,000 \u2192 with 5 years\u2019 experience \u00a340,000-\u00a360,000 \u2192 senior (10-15 years) up to \u00a375,000","UK mining/quarrying sector median (ONS, 2025) \u00a350,943","Qualifications: GCSEs incl. Maths and sciences \u2192 A-Levels \u2192 Mining/Geological Engineering degree \u2192 Chartered status via the Engineering Council \u2192 many British-trained engineers work abroad for large international mining companies"],"u":"https://en.wikipedia.org/wiki/Mining_engineering"},{"t":"Nuclear Facility/Reactor Operator","s":"Sellafield, EDF power stations","c":"Engineering & Design","k":27,"d":["Average around \u00a322,000-\u00a329,000, Royal Navy nuclear-qualified operators (see Submariner elsewhere in this guide) can reach \u00a348,000-\u00a352,000","Monitors plant operation and equipment, handles waste, and responds to emergencies in complex, highly regulated environments","Qualifications: no degree required for most operator roles \u2192 vocational training and mandatory radiological safety certification \u2192 apprenticeships available at major sites like EDF\u2019s Hinkley Point"],"u":"https://en.wikipedia.org/wiki/Nuclear_power_plant"},{"t":"Nuclear Engineer","s":"","c":"Engineering & Design","k":47,"d":["Distinct from Nuclear Facility Operator elsewhere in this guide - designs and analyses reactor systems rather than operating them day-to-day","Average around \u00a337,545-\u00a347,067, typical range \u00a331,000-\u00a373,000","A genuinely diverse sector, with professionals commonly transitioning in from healthcare, rail, oil & gas or aerospace given transferable safety and control-systems skills","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Engineering/Physics degree, often followed by a postgraduate MSc \u2192 Chartered status via the Nuclear Institute or Engineering Council for senior roles"],"u":"https://en.wikipedia.org/wiki/Nuclear_engineering"},{"t":"Net Zero/Sustainability Consultant","s":"","c":"Engineering & Design","k":50,"d":["A genuinely clear career ladder: Analyst \u00a330,000-\u00a345,000 \u2192 Consultant \u00a342,000-\u00a362,000 \u2192 Senior \u00a362,000-\u00a390,000 \u2192 Director \u00a3100,000-\u00a3180,000, Big Four partners considerably higher still","Advises on reducing carbon emissions and meeting the UK\u2019s Net Zero by 2050 targets","Qualifications: GCSEs \u2192 A-Levels \u2192 degree (environmental science/engineering helps, not always essential) \u2192 IEMA or GHG Protocol certifications add real value \u2192 one of the fastest-growing sectors in the UK job market right now"],"u":"https://en.wikipedia.org/wiki/Sustainability_consultant"},{"t":"Retrofit Coordinator","s":"Net Zero industry","c":"Engineering & Design","k":40,"d":["Highly experienced coordinators can earn over \u00a350,000","Oversees energy-efficiency upgrades to existing homes - insulation, heat pumps, ventilation - making them warmer and cheaper to heat, one of the fastest ways to cut carbon emissions","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 Retrofit Coordinator qualification meeting PAS 2035 standards (achievable without a degree) \u2192 coordinates assessors, designers, engineers and installers on each project"],"u":"https://en.wikipedia.org/wiki/Retrofitting"},{"t":"Structural Engineer","s":"","c":"Engineering & Design","k":46,"d":["Average around \u00a342,000-\u00a348,000, entry-level \u00a345,660 \u2192 senior/8+ years \u00a360,000-\u00a375,000+, directors and partners can exceed \u00a390,000","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Structural/Civil Engineering degree (many now hold a Master\u2019s) \u2192 Chartered Engineer (CEng) status adds \u00a35,000-\u00a310,000 over non-chartered peers"],"u":"https://en.wikipedia.org/wiki/Structural_engineering"},{"t":"Fire Safety Engineer","s":"","c":"Engineering & Design","k":45,"d":["Starting around \u00a326,000 \u2192 experienced professionals \u00a370,000+, senior London consultancy roles \u00a356,000-\u00a366,000","Applies engineering and science to protect buildings and people from fire risk - designing protection systems, running risk assessments, ensuring regulatory compliance","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Fire Engineering/relevant engineering degree \u2192 genuine, growing demand following increased building safety regulation across the UK"],"u":"https://en.wikipedia.org/wiki/Fire_protection_engineering"},{"t":"Acoustic Consultant","s":"","c":"Engineering & Design","k":34,"d":["Average around \u00a334,176, typical range \u00a329,637-\u00a345,139","Advises on sound and noise control in building design - insulation, vibration, environmental noise assessments for planning applications","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels \u2192 Acoustics/Physics/Engineering degree, often a specialist Master\u2019s \u2192 Institute of Acoustics membership adds real professional recognition"],"u":"https://en.wikipedia.org/wiki/Acoustical_engineering"},{"t":"CAD Technician","s":"Computer-Aided Design","c":"Engineering & Design","k":34,"d":["Average around \u00a334,237, entry-level roles considerably lower (\u00a318,600) rising past \u00a360,000 for specialists in high demand","Qualifications: GCSEs \u2192 A-Levels or a Level 3 apprenticeship (no degree needed) \u2192 proficiency in AutoCAD/Revit software matters more than formal qualifications \u2192 a genuinely accessible entry point into architecture, engineering and construction"],"u":"https://en.wikipedia.org/wiki/Computer-aided_design"},{"t":"Mechanical Engineer","s":"","c":"Engineering & Design","k":45,"d":["Entry-level graduate around \u00a327,000-\u00a331,000","Non-chartered experienced (5-10 years) \u00a348,000 median","Chartered (CEng MICE-equivalent) \u00a355,000 median, adding \u00a310,000-\u00a320,000 over non-chartered","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels (Maths, Physics) \u2192 Mechanical Engineering degree (3-4 years) \u2192 Chartered Engineer status via the Institution of Mechanical Engineers, several more years of experience"],"u":"https://en.wikipedia.org/wiki/Mechanical_engineer"},{"t":"Interior Designer","s":"","c":"Engineering & Design","k":40,"d":["Entry-level \u00a328,000-\u00a332,000 \u2192 average around \u00a334,000-\u00a344,000 \u2192 senior/studio leaders \u00a349,000-\u00a365,000+","Qualifications: GCSEs \u2192 A-Levels (Art/Design) \u2192 Interior Design degree (3 years, not always essential with a strong portfolio) \u2192 specialising in sustainable design or BIM/Revit software boosts pay"],"u":"https://en.wikipedia.org/wiki/Interior_design"},{"t":"Electrical Engineer","s":"","c":"Engineering & Design","k":40,"d":["Average around \u00a336,930-\u00a343,326 depending on source and sector (power, transport, defence, renewables)","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels (Maths, Physics) \u2192 Electrical Engineering degree (3-4 years) \u2192 Chartered Engineer (CEng) status via the Institution of Engineering and Technology (IET) lifts pay 15-25% over non-chartered"],"u":"https://en.wikipedia.org/wiki/Electrical_engineer"},{"t":"Journalist","s":"","c":"Creative & Hospitality","k":36,"d":["Average around \u00a336,093","Highly variable by outlet - national broadcasters/papers pay considerably more than local press","Qualifications: GCSEs \u2192 A-Levels \u2192 Journalism or English degree (not always required) or an NCTJ diploma \u2192 many start in local press or as a freelancer before moving to bigger outlets"],"u":"https://en.wikipedia.org/wiki/Journalist"},{"t":"Event Planner","s":"","c":"Creative & Hospitality","k":31,"d":["Average around \u00a330,700 nationally","London/senior planners \u00a355,000-\u00a362,000, entry-level \u00a320,000-\u00a328,000","Qualifications: GCSEs \u2192 A-Levels \u2192 Events Management degree (not always required) \u2192 often builds up via hospitality or venue coordination roles first"],"u":"https://en.wikipedia.org/wiki/Event_management"},{"t":"Wedding Planner/Coordinator","s":"","c":"Creative & Hospitality","k":20,"d":["Distinct from the general Event Planner elsewhere in this guide - genuinely lower-paid despite the glamorous image, since most start on a coordinator salary before building an independent client base","Average around \u00a320,309, typical range \u00a317,000-\u00a325,000 employed \u2192 self-employed planners with an established reputation and referral network can earn considerably more per wedding","Qualifications: no degree needed \u2192 GCSEs sufficient \u2192 organisation, budgeting and people skills matter more than any qualification"],"u":"https://en.wikipedia.org/wiki/Wedding_planner"},{"t":"Bartender","s":"","c":"Creative & Hospitality","k":26,"d":["Median around \u00a326,437, base pay typically \u00a318,000-\u00a324,000 before tips (which are legally protected and go entirely to staff)","Qualifications: no formal qualifications required \u2192 specialising in cocktail mixology or wine, or moving into bar management, increases earnings"],"u":"https://en.wikipedia.org/wiki/Bartender"},{"t":"Hotel Manager","s":"","c":"Creative & Hospitality","k":36,"d":["Average around \u00a335,600","Qualifications: GCSEs \u2192 A-Levels \u2192 Hospitality Management degree (not always required) \u2192 usually builds up through front-of-house, reception or department management roles first"],"u":"https://en.wikipedia.org/wiki/Hotel_manager"},{"t":"Waiter/Waitress","s":"front of house","c":"Creative & Hospitality","k":22,"d":["Base pay around \u00a321,000-\u00a323,000 plus tips, which are legally protected and go entirely to staff since 2024","Genuine progression route: experienced waiting staff are well placed to move up to front-of-house supervisor, Restaurant Manager, or even into the kitchen (Chef de Partie, Sous Chef)","Qualifications: no formal qualifications required \u2192 a genuinely accessible entry point into hospitality with real promotion paths for anyone who takes it seriously"],"u":"https://en.wikipedia.org/wiki/Waiting_staff"},{"t":"Restaurant Manager","s":"","c":"Creative & Hospitality","k":33,"d":["Distinct from Hotel Manager elsewhere in this guide - runs the front-of-house operation of a single restaurant","Entry-level \u00a324,000-\u00a326,000 \u2192 average around \u00a327,900-\u00a334,400 \u2192 experienced/senior \u00a330,000-\u00a345,000, London considerably higher, up to \u00a355,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 usually builds up from waiting staff or supervisor roles \u2192 Level 4 Diploma in Hospitality Management accelerates progression"],"u":"https://en.wikipedia.org/wiki/Restaurant_management"},{"t":"Golf Club Manager","s":"","c":"Creative & Hospitality","k":31,"d":["Early-career average \u00a327,304 \u2192 mid-career \u00a331,143, typical range \u00a327,000-\u00a355,000 \u2192 senior GM at a large private club can reach six figures","Runs the whole club - finance, course upkeep, bar and catering, staffing and member events, not just golf","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 PGA of GB&I Business Management qualifications are ideal for a PGA Professional (see that entry) moving into club management"],"u":"https://en.wikipedia.org/wiki/Golf_club"},{"t":"Golf Professional","s":"PGA Pro","c":"Creative & Hospitality","k":31,"d":["Distinct from the tour golfers shown in this app\u2019s Sport section - teaches lessons and runs the pro shop at a club rather than competing","Average around \u00a326,000-\u00a332,000, typical range \u00a321,240-\u00a347,523 \u2192 employed pros get a fixed salary with limited upside, while self-employed teaching pros can earn more but manage their own tax and pension","Qualifications: PGA qualification (FdSc or DipHE in Professional Golf), tuition around \u00a34,750/year UK/ROI - a real upfront cost like the Pilot and Barrister entries elsewhere in this guide"],"u":"https://en.wikipedia.org/wiki/PGA_of_Great_Britain_and_Ireland"},{"t":"TV Camera Operator","s":"","c":"Creative & Hospitality","k":55,"d":["Genuinely freelance-driven work with union (Bectu) recommended day rates, not a fixed salary","Camera assistant on factual/outside broadcast work \u00a3230-\u00a3360/day \u2192 full cameraperson \u00a3350-\u00a3485/day","Actual annual earnings depend heavily on how many days get booked across the year, which varies a lot person to person","Qualifications: no fixed degree route \u2192 many start as camera assistants/runners and work up through experience \u2192 covers everything from studio programmes to live sport and news"],"u":"https://en.wikipedia.org/wiki/Camera_operator"},{"t":"Sound/Recording Engineer","s":"TV, film, radio","c":"Creative & Hospitality","k":30,"d":["Starting around \u00a320,000 \u2192 with experience \u00a325,000 \u2192 long-term experienced engineers with strong technical skills can exceed \u00a340,000","Many work freelance, negotiating fees per production","Qualifications: no degree strictly required \u2192 college/HND courses in audio engineering or sound production help \u2192 sets up, operates and maintains the equipment that records and mixes sound for broadcast"],"u":"https://en.wikipedia.org/wiki/Audio_engineer"},{"t":"Photographer","s":"","c":"Creative & Hospitality","k":30,"d":["Entry-level \u00a321,553 \u2192 UK average \u00a324,350-\u00a329,786 \u2192 wedding/commercial/fashion specialists \u00a340,000-\u00a360,000+, some six-figure earners in London","Genuinely counter-intuitive structural point worth knowing: freelancers average just \u00a318,821, actually LESS than employed staff photographers at \u00a336,248 - the glamorous self-employed image doesn\u2019t match the typical reality until a strong client base is built","Qualifications: no degree required \u2192 short courses/certifications help \u2192 a strong portfolio and specialising in one niche (weddings, sport, products) matter far more than formal qualifications"],"u":"https://en.wikipedia.org/wiki/Photographer"},{"t":"Set Designer","s":"theatre, TV, film","c":"Creative & Hospitality","k":25,"d":["Starting salaries \u00a315,000-\u00a320,000 \u2192 UK average around \u00a331,478, typical range \u00a324,700-\u00a340,000 \u2192 experienced/senior designers on major productions can reach \u00a353,000-\u00a366,000+","Genuinely freelance-driven work, paid per production or a weekly rate rather than a fixed salary - unpaid work is common when starting out, and BECTU/Equity publish recommended minimum rates","Qualifications: no fixed degree route \u2192 Theatre/Production/Art & Design degree helps, though many build a portfolio and work up through assistant roles instead"],"u":"https://en.wikipedia.org/wiki/Set_construction"},{"t":"TV Outside Broadcast Engineer","s":"","c":"Creative & Hospitality","k":40,"d":["Starting salaries \u00a322,000-\u00a330,000 (BBC engineering apprenticeship starts \u00a319,500 plus London weighting) \u2192 experienced engineers \u00a330,000-\u00a360,000, senior roles at major broadcasters higher still","Genuinely varied and sometimes demanding work - can involve remote locations, poor weather, and occasionally hazardous assignments like conflict zone reporting","Qualifications: GCSEs incl. sciences \u2192 A-Levels \u2192 HNC/HND or degree in electrical/electronic engineering (though apprenticeship routes also exist) \u2192 sets up and maintains the technical equipment behind live TV broadcasts"],"u":"https://en.wikipedia.org/wiki/Broadcast_engineering"},{"t":"Florist","s":"","c":"Creative & Hospitality","k":26,"d":["Average around \u00a323,400-\u00a329,856, starting pay for junior florists often just \u00a313,000-\u00a318,000","Genuine nuance: a busy wedding florist doing 30-50 weddings a year can generate \u00a360,000-\u00a3100,000 in gross revenue, but flower costs alone eat 25-35% of that before any other expenses","Qualifications: no formal qualifications required, creativity and people skills matter more \u2192 one of the most accessible creative trades to enter, physically demanding and often poorly paid at entry level"],"u":"https://en.wikipedia.org/wiki/Florist"},{"t":"Croupier/Casino Dealer","s":"","c":"Creative & Hospitality","k":27,"d":["Average around \u00a320,750-\u00a332,275 depending on source, London new starters around \u00a317,000 rising to \u00a320,000+ within a couple of years \u2192 progression to Inspector can reach \u00a328,000+ plus tips within 5 years","Qualifications: no formal qualifications required \u2192 an NVQ in Gaming exists, but most learn entirely on the job \u2192 shift work including nights, weekends and bank holidays is standard"],"u":"https://en.wikipedia.org/wiki/Croupier"},{"t":"Makeup Artist","s":"","c":"Creative & Hospitality","k":22,"d":["National average around \u00a320,158-\u00a325,537","Freelancers just starting out often earn \u00a38,000-\u00a312,000 in year one \u2192 the freelance route has the highest ceiling but the biggest risk, since income is uneven and kit/travel costs come out of your own pocket","Qualifications: no formal qualifications legally required, though a diploma in makeup artistry helps build client trust \u2192 specialising in bridal, film/TV or special effects work pays considerably more than counter retail work"],"u":"https://en.wikipedia.org/wiki/Make-up_artist"},{"t":"Chef","s":"","c":"Creative & Hospitality","k":33,"d":["Commis Chef (entry) around \u00a320,000-\u00a324,000","Chef de Partie \u00a324,000-\u00a336,000","Sous Chef \u00a329,000-\u00a340,000","Head Chef \u00a335,000-\u00a357,000 (London average \u00a340,600)","Qualifications: no formal qualifications strictly required, though a Professional Cookery qualification or apprenticeship helps \u2192 works up through the kitchen \u201cbrigade\u201d hierarchy from Commis to Head Chef"],"u":"https://en.wikipedia.org/wiki/Chef"},{"t":"Graphic Designer","s":"","c":"Creative & Hospitality","k":32,"d":["Junior \u00a315,500-\u00a325,000","Mid-level \u00a332,500","Senior \u00a347,500","Freelance/established commercial designers can earn \u00a330-\u00a360/hour","Qualifications: GCSEs \u2192 A-Levels (Art/Design) \u2192 Graphic Design degree (3 years) OR a strong self-built portfolio is increasingly accepted without a degree in this field"],"u":"https://en.wikipedia.org/wiki/Graphic_design"},{"t":"Personal Trainer","s":"","c":"Creative & Hospitality","k":30,"d":["Typical range \u00a320,000-\u00a360,000, heavily dependent on employed vs self-employed and clientele built","Qualifications: GCSEs \u2192 CIMSPA-recognised Level 2 and Level 3 Personal Training qualifications, achievable in a few months, not years \u2192 no degree needed, though building a client base takes time"],"u":"https://en.wikipedia.org/wiki/Personal_trainer"},{"t":"Gym/Fitness Club Manager","s":"","c":"Creative & Hospitality","k":36,"d":["Trainee/assistant manager from \u00a324,000 \u2192 average around \u00a335,840, London \u00a337,550-\u00a341,890 \u2192 large multi-facility leisure centre GMs can exceed \u00a350,000","Qualifications: GCSEs \u2192 A-Levels \u2192 degree not always required \u2192 usually builds up from Fitness Instructor or Personal Trainer roles, plus a management/leisure qualification \u2192 bonuses tied to membership retention and new sign-ups are common"],"u":"https://en.wikipedia.org/wiki/Gym"},{"t":"Fitness Instructor","s":"","c":"Creative & Hospitality","k":22,"d":["Distinct from Personal Trainer elsewhere in this guide - employed gym staff running group classes and inductions, rather than self-employed one-to-one coaching","Average around \u00a322,500, range \u00a317,200-\u00a335,000+ (cruise ship instructors often the highest paid)","Qualifications: GCSEs \u2192 CIMSPA-recognised Level 2 Fitness Instructor qualification, achievable in weeks \u2192 no degree needed \u2192 a common, genuinely accessible first step before progressing to Personal Trainer or Gym Manager"],"u":"https://en.wikipedia.org/wiki/Physical_fitness_trainer"},{"t":"Air Traffic Controller","s":"NATS","c":"Transport","k":50,"d":["Trainees earn \u00a322,375 plus accommodation while training \u2192 rises to \u00a336,000 after basic training (12-15 months) \u2192 qualified \u00a348,480-\u00a354,032 \u2192 experienced controllers at busy units (Heathrow, Swanwick) can exceed \u00a3100,000 with shift pay","Qualifications: GCSEs \u2192 no degree required at all \u2192 rigorous NATS selection process (aptitude tests, psychometric testing, medical) \u2192 genuinely one of the highest-paid careers here with no university needed"],"u":"https://en.wikipedia.org/wiki/Air_traffic_controller"},{"t":"Airport Ground/Ramp Staff","s":"baggage handling, aircraft turnaround, check-in","c":"Transport","k":25,"d":["Entry-level \u00a318,000-\u00a322,000 \u2192 supervisory roles \u00a330,000+ \u2192 clear progression path from Ramp Agent through Team Leader to Duty Manager","Qualifications: no formal qualifications required to start, though an Airside Pass and enhanced background checks are mandatory \u2192 physically demanding outdoor work in all weather, at major hubs like Heathrow language skills attract a genuine pay premium"],"u":"https://en.wikipedia.org/wiki/Ground_handling"},{"t":"Aircraft Maintenance Engineer","s":"AME","c":"Transport","k":55,"d":["Trainee \u00a325,000-\u00a330,000 \u2192 headline averages often quoted around \u00a331,000-\u00a355,000, but this understates reality \u2192 licensed engineers (Part 66 B1/B2) with full shift patterns and aircraft type ratings realistically earn \u00a375,000-\u00a3108,000 all-in","Qualifications: GCSEs incl. sciences \u2192 CAA-approved apprenticeship or aviation engineering diploma (no degree required) \u2192 2-5 years to become fully licensed \u2192 the licence, not just experience, is what unlocks the real pay jump"],"u":"https://en.wikipedia.org/wiki/Aircraft_maintenance_technician"},{"t":"Train Driver","s":"","c":"Transport","k":69,"d":["Trainee pay \u00a323,000-\u00a340,000 depending on operator, training fully funded (12-18 months) \u2192 average qualified salary around \u00a369,000 (post-2024 ASLEF settlement) \u2192 with rest-day working, \u00a380,000+ is common, top operators can exceed \u00a3100,000","Qualifications: GCSEs \u2192 no degree required \u2192 operator-run training programme, genuinely one of the best-paid non-graduate careers in the UK"],"u":"https://en.wikipedia.org/wiki/Train_driver"},{"t":"London Underground Driver","s":"Tube","c":"Transport","k":55,"d":["Distinct from mainline Train Driver elsewhere in this guide - a separate TfL pay structure, not National Rail","Worth being careful here: media headlines widely quote \u00a370,000-\u00a380,000, but TfL\u2019s own official statement puts average BASE pay at \u00a355,011, with the overwhelming majority earning \u00a370,000 or less in total once overtime and pension contributions are included","Trainees start around \u00a335,000 during 12-16 weeks of training","Qualifications: no degree needed \u2192 external vacancies are genuinely rare, over 90% of drivers are promoted from within TfL, commonly from station/customer service roles \u2192 free travel across the whole TfL network for the driver and a nominated guest"],"u":"https://en.wikipedia.org/wiki/London_Underground"},{"t":"London Underground Station/Customer Service Assistant","s":"","c":"Transport","k":28,"d":["Distinct from Tube Driver elsewhere in this guide - the genuine entry point into TfL, and the most common route toward eventually becoming a driver","Entry-level \u00a325,000-\u00a332,000","Assists passengers, sells tickets, handles safety checks and station operations","Qualifications: no degree needed \u2192 GCSEs sufficient \u2192 TfL-run training provided \u2192 a genuinely accessible first step into one of London\u2019s best-paid public transport career ladders"],"u":"https://en.wikipedia.org/wiki/London_Underground"},{"t":"Taxi Driver","s":"","c":"Transport","k":40,"d":["Average around \u00a339,702, though this varies hugely by city and hours worked (range \u00a325,420-\u00a379,617)","London black cab drivers can reach \u00a345,000+","Qualifications: no degree needed \u2192 licence from local council, and for London black cabs, \u201cThe Knowledge\u201d exam which typically takes 2-4 years to pass \u2192 no university required, but genuinely demanding to qualify for the top tier"],"u":"https://en.wikipedia.org/wiki/Taxicabs_of_the_United_Kingdom"},{"t":"Warehouse Manager","s":"","c":"Transport","k":30,"d":["Average around \u00a329,800","Typical range \u00a323,000-\u00a342,000 depending on operation size","Qualifications: no degree required \u2192 usually builds up from warehouse operative/supervisor roles \u2192 forklift licence and logistics qualifications (e.g. CILT) help progression"],"u":"https://en.wikipedia.org/wiki/Warehouse"},{"t":"Freight Forwarder","s":"","c":"Transport","k":30,"d":["Average around \u00a325,490-\u00a332,182, typical range \u00a323,681-\u00a340,953","Acts on behalf of importers and exporters, arranging the safest and most cost-effective transport for goods by sea, air or road","Qualifications: GCSEs \u2192 A-Levels not always required \u2192 no degree needed to start \u2192 CILT (Chartered Institute of Logistics and Transport) qualifications available while working, genuinely accessible entry into international trade"],"u":"https://en.wikipedia.org/wiki/Freight_forwarder"},{"t":"Merchant Navy Officer","s":"","c":"Transport","k":39,"d":["Average around \u00a338,806","Genuinely distinctive lifestyle - typically several months at sea followed by extended leave, tax-free earnings possible for those meeting eligible-days-at-sea rules","Qualifications: GCSEs \u2192 no degree required \u2192 Merchant Navy cadetship (often fully funded by shipping companies) \u2192 Officer of the Watch certification"],"u":"https://en.wikipedia.org/wiki/Merchant_navy"},{"t":"Master Mariner/Ship\u2019s Captain","s":"","c":"Transport","k":120,"d":["The top of the Merchant Navy officer ladder shown alongside this app\u2019s other Merchant Navy entry","A genuinely clean progression: cadet allowance \u00a38,000-\u00a310,500 \u2192 Third Officer \u00a330,000 \u2192 Second Officer \u00a348,000 \u2192 Chief Officer \u00a378,000 \u2192 Master (Captain) \u00a3120,000+","Earnings on foreign-going ships (183+ days a year outside the UK) can be entirely tax-free","Qualifications: GCSEs \u2192 Merchant Navy cadetship \u2192 progression typically takes 10-15 years from cadet to captain \u2192 free food and accommodation at sea on top of salary"],"u":"https://en.wikipedia.org/wiki/Master_mariner"},{"t":"Marine Engineer","s":"","c":"Transport","k":41,"d":["Distinct from Merchant Navy Officer elsewhere in this guide - maintains and repairs a ship\u2019s engines and mechanical systems rather than navigating","Average around \u00a339,000-\u00a341,000, Aberdeen/Bristol/London \u00a348,000-\u00a355,000","Qualifications: GCSEs incl. Maths and Physics \u2192 A-Levels or a Marine Engineering apprenticeship (no degree required) \u2192 genuinely transferable skills between commercial shipping, offshore energy and naval roles"],"u":"https://en.wikipedia.org/wiki/Marine_engineering"},{"t":"Marine/Harbour Pilot","s":"","c":"Transport","k":55,"d":["Average around \u00a348,000-\u00a360,000, London considerably higher at \u00a374,568, senior pilots exceeding \u00a383,000","A genuinely elite, highly specialised role - boards vessels to guide them safely into and out of busy harbours, coordinating with tugs and port control","Qualifications: virtually always former ship\u2019s officers or captains with extensive command experience \u2192 specialist pilotage exams and local waters knowledge required \u2192 not an entry-level route, but a genuinely well-paid specialism at the top of a maritime career"],"u":"https://en.wikipedia.org/wiki/Maritime_pilot"},{"t":"Port/Gantry Crane Operator","s":"container terminals","c":"Transport","k":36,"d":["Distinct from the construction Plant Operator elsewhere in this guide - operates dedicated container-handling gantry cranes rather than excavators or mobile cranes","Average around \u00a331,000-\u00a343,600","Qualifications: no degree needed \u2192 Port Operative Level 2 apprenticeship (1-2 years, on-the-job plus study) \u2192 trains specifically on gantry cranes and lifting machinery in a cargo terminal environment"],"u":"https://en.wikipedia.org/wiki/Container_crane"},{"t":"Delivery Driver/Courier","s":"","c":"Transport","k":26,"d":["Most earn \u00a312-\u00a320/hour, roughly \u00a325,000-\u00a331,000 full-time equivalent","Self-employed multi-drop and van drivers often sit higher, \u00a3110-\u00a3250 per shift","Qualifications: no degree needed, standard driving licence sufficient for most roles (van driving may need a category B+E test) \u2192 genuinely one of the fastest, most accessible ways into paid work"],"u":"https://en.wikipedia.org/wiki/Delivery_(commerce)"},{"t":"Air Cabin Crew/Flight Attendant","s":"","c":"Transport","k":25,"d":["Starting salary around \u00a319,000-\u00a325,000 base, total earnings with flight duty pay and allowances often \u00a326,000-\u00a332,000 \u2192 senior long-haul crew can reach \u00a350,000","Qualifications: no degree needed \u2192 airline-run training (4-6 weeks) or a Cabin Crew Level 3 apprenticeship \u2192 staff travel benefits and hotel stays add real value beyond base pay"],"u":"https://en.wikipedia.org/wiki/Flight_attendant"},{"t":"Bus Driver","s":"","c":"Transport","k":31,"d":["Average around \u00a328,000-\u00a334,000, London TfL-contracted drivers \u00a333,000-\u00a344,000","Qualifications: no degree needed \u2192 standard driving licence \u2192 PCV (Passenger Carrying Vehicle) licence, often funded by the employer \u2192 genuine driver shortage since the pandemic has pushed pay up faster than most other transport roles"],"u":"https://en.wikipedia.org/wiki/Bus_driver"},{"t":"Commercial Airline Pilot","s":"","c":"Transport","k":90,"d":["First Officers at regional airlines \u00a345,000-\u00a370,000","Captains at major carriers (BA, easyJet, Virgin) \u00a3100,000-\u00a3200,000","Long-haul senior captains \u00a3150,000-\u00a3250,000+","Qualifications: GCSEs \u2192 A-Levels \u2192 Air Transport Pilot Licence (ATPL) via a CAA-approved flight school","Unlike most careers here, this route costs the trainee \u00a380,000-\u00a3120,000 upfront rather than being paid to learn"],"u":"https://en.wikipedia.org/wiki/Airline_pilot"},{"t":"HGV/Lorry Driver","s":"","c":"Transport","k":35,"d":["Class 2 (rigid) drivers \u00a328,000-\u00a336,000","Class 1 (articulated) drivers \u00a332,000-\u00a350,000, specialists/nights up to \u00a355,000+","Qualifications: no degree or A-Levels needed","Class 2 licence costs \u00a31,500-\u00a33,000 and takes weeks, not years","Many employers fund training in exchange for a minimum period of service"],"u":"https://en.wikipedia.org/wiki/Truck_driver"},{"t":"Petrol/Fuel Tanker Driver","s":"","c":"Transport","k":42,"d":["A specialist add-on to HGV Driver elsewhere in this guide - transports hazardous liquids, commanding a real premium over standard haulage","Typical range \u00a335,000-\u00a355,000+, hourly rates often \u00a316-\u00a321+, with weekend and night premiums pushing this higher still","Qualifications: standard Class 1 HGV licence first \u2192 ADR (Dangerous Goods) certification specifically for tank vehicles, adding \u00a32,000-\u00a35,000 to salary \u2192 genuinely more responsibility than standard haulage given the cargo, reflected directly in the pay"],"u":"https://en.wikipedia.org/wiki/Tank_truck"},{"t":"Social Worker","s":"","c":"Public Service","k":42,"d":["Average around \u00a341,591, varies significantly by local authority and specialism (children\u2019s/adult social care)","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 3-year Social Work degree (BSc) or a postgraduate route \u2192 register with Social Work England"],"u":"https://en.wikipedia.org/wiki/Social_work"},{"t":"Coastguard","s":"Maritime Operations Officer","c":"Public Service","k":30,"d":["Starts around \u00a327,747 (base plus shift allowances) \u2192 Senior Coastal Operations Officer \u00a331,000-\u00a341,000","Qualifications: GCSEs \u2192 no degree required \u2192 Maritime and Coastguard Agency training programme \u2192 24-hour search and rescue coordination role"],"u":"https://en.wikipedia.org/wiki/HM_Coastguard"},{"t":"Border Force Officer","s":"","c":"Public Service","k":32,"d":["Starts \u00a328,000-\u00a332,000 (apprentices from \u00a324,800) \u2192 with experience \u00a334,000 \u2192 Higher Officer \u00a337,300-\u00a339,911 \u2192 senior managers can exceed \u00a360,000","Qualifications: GCSEs \u2192 no degree required \u2192 UK national with 5 years UK residency required \u2192 shift allowances can boost pay by up to 50%"],"u":"https://en.wikipedia.org/wiki/Border_Force"},{"t":"999 Call Handler","s":"","c":"Public Service","k":28,"d":["Average around \u00a328,364","Roles exist across police, ambulance and fire services, around 5,000-7,000 nationally, with regular recruitment","Shift work including nights, weekends and public holidays, covering 24-hour emergency cover","Qualifications: GCSEs \u2192 no degree required \u2192 genuinely demanding, high-pressure work staying calm while gathering critical information from callers in crisis"],"u":"https://en.wikipedia.org/wiki/Emergency_telephone_number"},{"t":"Probation Officer","s":"","c":"Public Service","k":31,"d":["Average around \u00a330,570, typical range \u00a327,000-\u00a354,000","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 Professional Qualification in Probation (PQiP), a paid trainee route combining work and study \u2192 no need to pay for a degree first \u2192 genuinely demanding work supervising offenders and assessing risk to protect the public"],"u":"https://en.wikipedia.org/wiki/Probation_officer"},{"t":"Environmental Health Officer","s":"","c":"Public Service","k":39,"d":["Average around \u00a338,536-\u00a346,474, London \u00a342,309-\u00a353,801 \u2192 entry-level \u00a325,000-\u00a335,000 \u2192 senior/managerial \u00a338,000-\u00a360,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 EHRB-accredited Environmental Health degree \u2192 register with the Chartered Institute of Environmental Health (CIEH) \u2192 covers food safety, housing standards and pollution control"],"u":"https://en.wikipedia.org/wiki/Environmental_health_officer"},{"t":"Health & Safety Officer","s":"HSE","c":"Public Service","k":55,"d":["High-risk environments - distinct from Environmental Health Officer elsewhere in this guide, focused on workplace hazards rather than public health","Entry \u00a325,000-\u00a340,000 \u2192 experienced HSE Officer \u00a336,000-\u00a348,000 \u2192 Tier 1 construction HSE Manager \u00a345,000-\u00a362,000 \u2192 offshore oil & gas HSE Manager, the highest-paying UK sector for this role, \u00a365,000-\u00a390,000+ plus allowances","Qualifications: no degree required \u2192 NEBOSH National General Certificate (achievable in weeks) \u2192 NEBOSH National Diploma for senior roles \u2192 a genuinely accessible, well-paid route protecting workers in construction, oil & gas and manufacturing"],"u":"https://en.wikipedia.org/wiki/Occupational_safety_and_health"},{"t":"Mountain Rescue Team Leader/Commander","s":"","c":"Public Service","k":0,"d":["Important honest reality worth knowing: in the UK this is genuinely NOT a paid career, even at leadership level","Mountain Rescue teams are volunteer-run charities, confirmed directly by their own published accounts (e.g. Woodhead MRT, Buxton MRT) stating no trustee or team member receives any remuneration","Around 3,500 volunteers cover the whole UK, funded almost entirely by donations and fundraising, with only occasional government grants","Genuinely skilled, demanding work (rope rescue, navigation, first aid, often at night in poor weather) done entirely unpaid out of a sense of community duty","There is an active Parliamentary campaign to give search and rescue volunteers the same paid-leave status as Army reservists, but this is not yet in place"],"u":"https://en.wikipedia.org/wiki/Mountain_rescue"},{"t":"Immigration/Border Enforcement Officer","s":"Home Office","c":"Public Service","k":32,"d":["Distinct from Border Force elsewhere in this guide - deals with people already in the UK rather than at the point of entry","Starts \u00a328,000, rising to \u00a329,400 with experience \u00a334,350-\u00a341,035 as Chief Immigration Officer, plus shift and unsocial hours allowances","Qualifications: must be a UK national \u2192 GCSEs \u2192 no degree required \u2192 shift work and unsocial hours are standard, with genuine promotion opportunities for those who want them"],"u":"https://en.wikipedia.org/wiki/UK_Visas_and_Immigration"},{"t":"Trading Standards Officer","s":"","c":"Public Service","k":40,"d":["Trainee \u00a326,400-\u00a331,000 \u2192 experienced \u00a332,000-\u00a343,000 \u2192 senior \u00a346,000+ \u2192 lead/chief officer \u00a350,000-\u00a355,000+ in larger councils","Protects consumers by enforcing weights and measures, product safety and fair trading law","Qualifications: GCSEs \u2192 A-Levels \u2192 Trading Standards degree/apprenticeship or a related degree plus professional qualification (DCATS/RPTSA) \u2192 genuinely varied work investigating scams, counterfeit goods and unsafe products"],"u":"https://en.wikipedia.org/wiki/Trading_Standards"},{"t":"Lifeguard","s":"RNLI beach or council pool","c":"Public Service","k":25,"d":["RNLI beach lifeguards paid \u00a311-\u00a315.15/hour, often seasonal work covering summer months \u2192 full-time pool lifeguards around \u00a325,185-\u00a325,989/year plus unsocial hours pay","Genuinely opens doors to other careers - many lifeguards move into leisure management, the emergency services or the armed forces afterwards","Qualifications: aged 16+ \u2192 National Vocational Beach Lifeguard Qualification or a UK pool lifeguard qualification (no degree needed, achievable in days) \u2192 must pass a fitness and swimming competency test"],"u":"https://en.wikipedia.org/wiki/Lifeguard"},{"t":"Funeral Director/Undertaker","s":"","c":"Public Service","k":39,"d":["Average around \u00a338,133-\u00a340,723","Coordinates the entire funeral process - liaising with grieving families, organising the ceremony, and handling legal paperwork","Qualifications: no formal academic requirements, though GCSEs are often expected \u2192 professional NAFD/BIFD certification available and genuinely boosts pay \u2192 a full driving licence usually required \u2192 emotionally demanding, meaningful work requiring real emotional intelligence"],"u":"https://en.wikipedia.org/wiki/Funeral_director"},{"t":"Embalmer","s":"","c":"Public Service","k":32,"d":["Distinct from Funeral Director elsewhere in this guide - a specialised technical role preserving the deceased\u2019s appearance for viewing and funeral","Apprentice \u00a326,000 \u2192 qualified \u00a329,000-\u00a338,123","Qualifications: no fixed academic requirement, though knowledge of chemistry, microbiology and anatomy genuinely helps \u2192 professional embalming qualifications available \u2192 a genuinely uncommon career choice, most funeral homes employ relatively few embalmers"],"u":"https://en.wikipedia.org/wiki/Embalming"},{"t":"Crematorium Technician/Operator","s":"","c":"Public Service","k":29,"d":["Average around \u00a329,108","Operates crematorium equipment safely, conducts body identification checks, and maintains the chapel between services \u2192 a genuinely essential, precise role requiring strict adherence to procedure and regulation","Qualifications: no formal academic requirements \u2192 training provided on the job \u2192 professional qualifications in crematorium technology available for career progression"],"u":"https://en.wikipedia.org/wiki/Crematory"},{"t":"Prison Officer","s":"HMPPS","c":"Public Service","k":30,"d":["Starts at \u00a328,373 (\u00a330,795 in London)","Experienced officers \u00a330,000-\u00a336,000, plus unsocial hours allowance","Custodial Managers \u00a336,000-\u00a348,000, Governors \u00a360,000-\u00a390,000+","Qualifications: GCSEs \u2192 HMPPS recruitment process (fitness, psychometric and situational judgement tests, no degree required) \u2192 in-service training"],"u":"https://en.wikipedia.org/wiki/Prison_officer"},{"t":"DVSA Driving Examiner","s":"","c":"Public Service","k":29,"d":["Distinct from Driving Instructor elsewhere in this guide - stable civil service employee rather than self-employed","Starts \u00a326,000-\u00a330,000 \u2192 with overtime and London weighting \u00a340,000-\u00a342,000+","Genuinely different lifestyle to instructing: predictable Monday-Friday hours, a Civil Service Pension, and completely free, paid training (no upfront cost, unlike the Driving Instructor route)","Qualifications: no degree needed, aged 23+ \u2192 7-week residential training course at DVSA Cardington \u2192 assesses 7-8 driving tests a day"],"u":"https://en.wikipedia.org/wiki/Driving_test"},{"t":"Police Officer","s":"","c":"Public Service","k":42,"d":["Full rank progression","Constable starts \u00a328,551, rising to \u00a346,044 with experience \u2192 Sergeant \u00a346,044-\u00a350,440 \u2192 Inspector \u00a357,162-\u00a359,840 \u2192 Chief Inspector \u00a355,000-\u00a361,000 \u2192 Superintendent/Chief Superintendent \u00a365,000-\u00a385,000+ \u2192 Assistant Chief Constable and above \u00a390,000-\u00a3111,000+, London officers get extra regional weighting on top","Qualifications: GCSEs \u2192 Police Constable Degree Apprenticeship (3 years, earn a salary while training and studying - no need to pay for university) or an existing degree with a shorter training route"],"u":"https://en.wikipedia.org/wiki/Police_officer"},{"t":"Detective","s":"CID","c":"Public Service","k":42,"d":["Distinct from the general Police Officer entry elsewhere in this guide - a common misconception worth clearing up: \u201cDetective\u201d is a specialism, not a promotion, and pays exactly the same as the equivalent uniformed rank","Some specialist units attract additional allowances on top","Investigates serious crime - murder, fraud, drugs - across CID or specialist squads","Qualifications: usually joins as a uniformed officer first, then applies to transfer into investigative work \u2192 further specialist detective training required"],"u":"https://en.wikipedia.org/wiki/Criminal_Investigation_Department"},{"t":"Armed Response/Firearms Officer","s":"","c":"Public Service","k":34,"d":["Another police specialism distinct from the general Police Officer entry elsewhere in this guide - not a separate rank, but a role requiring additional selection and training","Same base pay as an equivalent uniformed officer, plus a specialist role enhancement/allowance on top","Qualifications: must already be a serving police officer \u2192 rigorous firearms selection and training course, with regular ongoing requalification \u2192 among the most demanding, high-stakes specialisms in UK policing"],"u":"https://en.wikipedia.org/wiki/Authorised_firearms_officer"},{"t":"Civil Servant","s":"AO","c":"Public Service","k":45,"d":["A genuinely clean, well-documented career ladder: Administrative Officer \u00a322,450 \u2192 Executive Officer, the most common graduate entry point \u2192 Higher Executive Officer \u2192 Grade 7 \u00a357,000-\u00a363,000 \u2192 Senior Civil Service, up to \u00a3162,000+ at the very top","Pay varies noticeably by department and location, sometimes by \u00a310,000+ at the same grade","Qualifications: GCSEs \u2192 no degree required for AO/EO entry \u2192 the Civil Service Fast Stream offers an accelerated graduate route to senior roles \u2192 genuine job security and a strong pension are real, if less headline-grabbing, benefits"],"u":"https://en.wikipedia.org/wiki/Civil_Service_(United_Kingdom)"},{"t":"Member of Parliament","s":"MP","c":"Public Service","k":99,"d":["Through to Prime Minister","MP basic salary \u00a398,599 (2026) \u2192 junior ministers/parliamentary secretaries around \u00a3102,000-\u00a3121,000 \u2192 Cabinet Ministers roughly \u00a3115,000-\u00a3159,000 \u2192 Prime Minister\u2019s combined MP and ministerial salary around \u00a3182,000 (though PMs have sometimes chosen to draw less)","Genuinely unusual career: no fixed qualifications or route, elected rather than appointed, and can end abruptly at any general election regardless of performance","Most build a public profile through local politics, campaigning or another career first"],"u":"https://en.wikipedia.org/wiki/Member_of_Parliament_(United_Kingdom)"},{"t":"Local Councillor","s":"","c":"Public Service","k":25,"d":["Through to Council Leader - important distinction from the MP entry elsewhere in this guide: this is genuinely NOT a salary, it\u2019s an unpaid \u201cbasic allowance\u201d, typically \u00a39,000-\u00a316,000 a year","Doing a backbench ward councillor role properly for the hours it actually takes often works out close to minimum wage \u2192 Cabinet member/committee chair roles with a Special Responsibility Allowance can reach \u00a325,000-\u00a340,000 \u2192 Leader of a large council can be a genuine full-time income of \u00a350,000-\u00a375,000+","Qualifications: no fixed route \u2192 elected every 4 years \u2192 most do this alongside another job, especially at backbench level"],"u":"https://en.wikipedia.org/wiki/Councillor"},{"t":"Council Officer","s":"","c":"Public Service","k":40,"d":["Distinct from the elected Councillor entry elsewhere in this guide - an appointed, professional local government career, not an elected political one","Entry-level \u00a322,000-\u00a325,000 \u2192 progresses through Green Book grades \u2192 Director level considerably higher \u2192 Chief Executive, the most senior officer role, ranges from around \u00a3114,000 at a District Council up to \u00a3157,000-\u00a3184,000 at a County, Metropolitan or London Borough council","Qualifications: GCSEs \u2192 no degree required for entry \u2192 Local Government Pension Scheme (LGPS) and clear internal promotion pathways are genuine, if less headline-grabbing, benefits"],"u":"https://en.wikipedia.org/wiki/Local_government_in_England"},{"t":"Unemployment/Universal Credit","s":"","c":"Public Service","k":5,"d":["Not a career, but an honest and important part of understanding the UK financial system, since almost everyone experiences a gap between jobs at some point","Universal Credit standard allowance (2026/27): \u00a3424.90/month if single and 25+, \u00a3338.58/month if single under 25, \u00a3666.97/month for a couple 25+ - roughly \u00a35,100/year for a single adult on the standard allowance alone","Most claimants also receive additional elements on top for housing costs, children or health conditions, which can significantly increase the total","Genuinely temporary and means-tested for most people, with a dedicated work coach and real support (training, job search help) built into the system to help people back into paid work"],"u":"https://en.wikipedia.org/wiki/Universal_Credit"},{"t":"Firefighter","s":"","c":"Public Service","k":33,"d":["Starts around \u00a326,000-\u00a328,000","Experienced firefighters/crew managers reach \u00a338,000-\u00a342,000+","Qualifications: GCSEs \u2192 National firefighter selection tests (fitness, aptitude, situational judgement - highly competitive, no degree required) \u2192 in-service training"],"u":"https://en.wikipedia.org/wiki/Firefighter"},{"t":"British Army Soldier","s":"Private","c":"Armed Forces","k":27,"d":["Starts around \u00a321,000-\u00a326,000 during training","Trained Private reaches \u00a327,145","Lance Corporal \u00a330,815-\u00a334,920","Sergeant up to \u00a350,085","Qualifications: no degree needed, minimum age 16 with parental consent (or 18 without) \u2192 basic training \u2192 trade-specific training","Note: full package includes free healthcare, subsidised accommodation and pension, estimated 40-50% more valuable than base pay alone"],"u":"https://en.wikipedia.org/wiki/British_Army"},{"t":"British Army Officer","s":"","c":"Armed Forces","k":55,"d":["Second Lieutenant starts around \u00a332,988","Major \u00a357,500-\u00a375,000","Lieutenant Colonel \u00a378,000-\u00a394,000+","Qualifications: typically a degree (any subject) \u2192 Royal Military Academy Sandhurst (44-week commissioning course)","A degree-apprenticeship officer route also exists without needing to pay for university first"],"u":"https://en.wikipedia.org/wiki/Royal_Military_Academy_Sandhurst"},{"t":"Royal Navy Rating","s":"","c":"Armed Forces","k":26,"d":["Day one pay \u00a326,344+ \u2192 Leading Hand \u00a339,565+ \u2192 Petty Officer \u00a344,000+ \u2192 Warrant Officer \u00a366,585+","Qualifications: no degree needed, minimum age 16 with parental consent (or 18 without) \u2192 basic training \u2192 trade-specific training","Submariners earn extra pay plus a \u00a325,000 retention bonus after 6 years"],"u":"https://en.wikipedia.org/wiki/Royal_Navy"},{"t":"Royal Navy Submariner","s":"","c":"Armed Forces","k":32,"d":["Distinct from surface Royal Navy Rating elsewhere in this guide - a specialist qualification stacking real extra pay on top of standard Navy pay, not a separate entry route","\u00a35,000-\u00a37,500 bonus on qualifying (\u201cearning your Dolphins\u201d) \u2192 additional Submariner Pay of \u00a36,106-\u00a310,690/year once qualified \u2192 a further \u00a325,000 retention bonus after 6 years\u2019 qualified service","Genuinely unique lifestyle - months at a time submerged, extremely close quarters with the crew","Qualifications: joins as standard Rating or Officer first \u2192 dedicated submarine training \u2192 minimum height requirement of 157cm"],"u":"https://en.wikipedia.org/wiki/Submarine"},{"t":"Royal Navy Officer","s":"","c":"Armed Forces","k":47,"d":["Distinct from Royal Navy Rating elsewhere in this guide","Follows the same tri-service Armed Forces pay scale as Army and RAF officers - broadly \u00a340,000-\u00a357,000 through the middle ranks, senior officers higher still","Qualifications: typically a degree (any subject) \u2192 Britannia Royal Naval College Dartmouth commissioning course \u2192 commissioned officers take on greater leadership and command responsibility than ratings, reflected in higher pay"],"u":"https://en.wikipedia.org/wiki/Britannia_Royal_Naval_College"},{"t":"Fleet Air Arm Pilot","s":"Royal Navy aviation","c":"Armed Forces","k":42,"d":["Distinct from the general Royal Navy Officer elsewhere in this guide - flies helicopters and fixed-wing aircraft from ships at sea","Starts around \u00a334,676 from day one of training, rising with rank and experience \u2192 additional Aviation Incentive Pay for active flying, plus hazardous duty and deployment allowances on top of base salary","Qualifications: typically a degree \u2192 Initial Naval Officer Training \u2192 flight training \u2192 operates aircraft in genuinely challenging maritime conditions most pilots never encounter"],"u":"https://en.wikipedia.org/wiki/Fleet_Air_Arm"},{"t":"RAF Airman/Aircraftman","s":"","c":"Armed Forces","k":20,"d":["Trainees start around \u00a317,000-\u00a320,000 \u2192 rises with rank and trade qualifications \u2192 senior officers and pilots can exceed \u00a3120,000-\u00a3150,000","Qualifications: no degree needed for most trades, minimum age 16 with parental consent (or 18 without) \u2192 basic training \u2192 trade-specific training","Subsidised food and accommodation add real value beyond the base salary"],"u":"https://en.wikipedia.org/wiki/Royal_Air_Force"},{"t":"Royal Marines Commando","s":"","c":"Armed Forces","k":33,"d":["Starts over \u00a325,000, rising to \u00a351,000+ with progression, average around \u00a332,500","The Royal Navy\u2019s elite amphibious force, earning the coveted green beret","Qualifications: no degree needed \u2192 one of the most physically demanding training courses in the entire UK military \u2192 genuinely not for everybody, but a fast promotion track for those who complete it"],"u":"https://en.wikipedia.org/wiki/Royal_Marines"},{"t":"Parachute Regiment","s":"Paratrooper","c":"Armed Forces","k":26,"d":["Standard Army soldier pay - starts at \u00a326,334 minimum, same after basic trade training \u2192 additional specialist parachutist pay on top once qualified","The Army\u2019s Global Response Force, held at very high readiness to deploy first in emerging crises worldwide","Qualifications: no formal qualifications needed \u2192 famously the toughest selection process in the British Army (P Company), requiring exceptional fitness \u2192 genuinely not about pay, but about being part of one of the most demanding units in the military"],"u":"https://en.wikipedia.org/wiki/Parachute_Regiment"},{"t":"Army Dog Handler","s":"Royal Army Veterinary Corps","c":"Armed Forces","k":26,"d":["Standard Army soldier pay - starts at \u00a326,334, same after basic trade training","Trains and works with Military Working Dogs on operations worldwide - starting with protection dogs securing bases, later potentially specialist dogs trained to detect arms and explosives","A genuinely unique bond forms between handler and dog over a career","Qualifications: no formal qualifications needed, aged 17.5-35.5 \u2192 training at the Defence Animal Training Regiment \u2192 Level 2 Animal Care and Welfare Assistant Apprenticeship gained alongside service"],"u":"https://en.wikipedia.org/wiki/Royal_Army_Veterinary_Corps"},{"t":"RAF Officer","s":"","c":"Armed Forces","k":47,"d":["Average around \u00a347,329, typical range \u00a339,521-\u00a356,681 \u2192 highest seniority levels can reach \u00a391,397+","Qualifications: typically a degree (any subject) \u2192 RAF College Cranwell commissioning course \u2192 commissioned officers take on greater leadership responsibility than RAF Airmen elsewhere in this guide, reflected in higher pay"],"u":"https://en.wikipedia.org/wiki/Royal_Air_Force_College_Cranwell"},{"t":"RAF Regiment Gunner","s":"","c":"Armed Forces","k":26,"d":["Distinct from RAF Airman elsewhere in this guide - a specialist ground combat force protecting RAF airfields, not aircrew","Starts \u00a320,000-\u00a325,200 \u2192 experienced \u00a326,000-\u00a337,000","Specialises in dismounted close combat, weapons systems and surveillance, with near-certain overseas deployment within the first few years (Canada, Cyprus, Middle East, Africa)","Qualifications: no degree needed, aged 16-47 \u2192 HM Forces Serviceperson (Protective Services) Level 2 apprenticeship \u2192 Potential Gunner Selection Course fitness test required"],"u":"https://en.wikipedia.org/wiki/RAF_Regiment"},{"t":"Army Physical Training Instructor","s":"PTI","c":"Armed Forces","k":27,"d":["Follows standard Army rank-based pay, generally \u00a320,000-\u00a330,000+ \u2192 some sources cite \u00a334,000-\u00a351,000, but this figure comes from very few respondents and even Glassdoor rates it \u201clow confidence\u201d, so treat cautiously","Genuinely not a direct-entry role - you must already be serving in another Army trade before training as a PTI","Qualifications: no degree needed \u2192 Army PTI course (leadership, exercise science, fitness testing) \u2192 skills transfer well to civilian fitness consulting or wellness coaching after service, often \u00a330,000-\u00a370,000"],"u":"https://en.wikipedia.org/wiki/Physical_training_instructor"},{"t":"Royal Military Police","s":"","c":"Armed Forces","k":30,"d":["Follows standard British Army pay scales","Policing army personnel, investigating crimes and supporting operations both at home and abroad \u2192 genuinely distinct day-to-day role from front-line soldiering, for those drawn to law enforcement within a military structure","Qualifications: no degree needed \u2192 standard Army entry followed by RMP-specific training"],"u":"https://en.wikipedia.org/wiki/Royal_Military_Police"},{"t":"Royal Signals","s":"","c":"Armed Forces","k":33,"d":["Follows standard British Army pay scales, average around \u00a332,720","Provides the Army\u2019s communications - radios, networks and information systems keeping units connected on operations","Genuinely technical trade, transferable directly to civilian telecoms and IT careers after service","Qualifications: no degree needed for soldiers \u2192 trade-specific technical training \u2192 officer route requires a degree \u2192 Sandhurst commissioning \u2192 specialist Troop Commanders\u2019 Course covering satellite communication and network theory"],"u":"https://en.wikipedia.org/wiki/Royal_Corps_of_Signals"},{"t":"Army Chaplain","s":"Royal Army Chaplains\u2019 Department","c":"Armed Forces","k":60,"d":["Starting salary \u00a360,236, staying the same after basic trade training \u2192 rises with seniority","A genuinely unique role - chaplains hold no standard military ranks, instead unique \u201cChaplain to the Forces\u201d classes, and are universally addressed as \u201cpadre\u201d","Non-combatant, provides leadership but does not command","Qualifications: must already be an ordained/accredited minister in a recognised faith or belief community, aged 26-54 \u2192 provides pastoral care, spiritual support and moral guidance to soldiers and their families of any faith or none"],"u":"https://en.wikipedia.org/wiki/Royal_Army_Chaplains%27_Department"},{"t":"Army Legal Officer","s":"Army Legal Services","c":"Armed Forces","k":53,"d":["Starting salary during training \u00a360,236 \u2192 rises to a minimum of \u00a352,815 after completing basic trade training, then continues rising with rank \u2192 provides legal advice to commanders on operations, courts martial and military law","Qualifications: qualified solicitor or barrister (see those entries elsewhere in this guide for the route) \u2192 aged 21-32 to apply \u2192 combines a legal career with military service, including postings on operations"],"u":"https://en.wikipedia.org/wiki/Army_Legal_Services"},{"t":"Army Intelligence Officer","s":"Intelligence Corps","c":"Armed Forces","k":40,"d":["Average around \u00a337,641-\u00a340,000, rising with rank like other Army officer roles","Gathers, analyses and assesses information to support military decision-making, working across intelligence, communications and IT specialisms","Qualifications: typically a degree \u2192 Royal Military Academy Sandhurst commissioning course \u2192 further specialist intelligence training \u2192 requires security clearance and discretion beyond most other Army roles"],"u":"https://en.wikipedia.org/wiki/Intelligence_Corps_(United_Kingdom)"},{"t":"Royal Engineers Officer","s":"","c":"Armed Forces","k":40,"d":["Officer Cadet at Sandhurst \u00a335,925 \u2192 Second Lieutenant \u00a342,948 \u2192 Captain \u00a354,716 \u2192 Major \u00a368,624","Genuinely varied combat-engineering role: bridging rivers, clearing minefields, building runways, bomb disposal","Qualifications: typically a degree \u2192 44-week Sandhurst commissioning course \u2192 can achieve Chartered Engineer status via the IET while serving"],"u":"https://en.wikipedia.org/wiki/Royal_Engineers"},{"t":"REME Vehicle Mechanic","s":"Royal Electrical and Mechanical Engineers","c":"Armed Forces","k":27,"d":["Follows standard British Army pay scales, starting around \u00a326,334","Genuinely distinct technical trade role - keeps everything from Land Rovers to tanks running, sometimes in extreme conditions on operations","Qualifications: no degree needed \u2192 Level 3 Heavy Vehicle Servicing and Maintenance Technician Apprenticeship provided during training \u2192 skills transfer directly to civilian vehicle mechanic work after service"],"u":"https://en.wikipedia.org/wiki/Royal_Electrical_and_Mechanical_Engineers"},{"t":"Farm Worker","s":"","c":"Land & Nature","k":28,"d":["Average around \u00a328,109","Qualifications: often no formal qualifications required to start - many begin as teenagers on family or local farms \u2192 NVQs/City & Guilds in Agriculture available and useful for progression to farm manager \u2192 tractor/machinery certificates add value \u2192 genuinely essential, physically demanding outdoor work"],"u":"https://en.wikipedia.org/wiki/Farmworker"},{"t":"Farm Manager","s":"","c":"Land & Nature","k":40,"d":["Average around \u00a335,500-\u00a341,400","Typical range \u00a330,000-\u00a370,000 depending on farm size and specialism","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 Agriculture/Farm Management degree, HND or apprenticeship route (degree not always required with enough practical experience) \u2192 usually progresses from Farm Worker"],"u":"https://en.wikipedia.org/wiki/Farm_manager"},{"t":"Gamekeeper","s":"","c":"Land & Nature","k":26,"d":["Average around \u00a326,000-\u00a336,000, though pay varies enormously by estate and region (as low as \u00a317,000 in some areas)","Qualifications: no formal qualifications required, GCSEs sufficient \u2192 relevant college courses in Gamekeeping/Countryside Management help \u2192 often starts as an underkeeper before progressing to head keeper on a larger estate"],"u":"https://en.wikipedia.org/wiki/Gamekeeper"},{"t":"Farrier","s":"","c":"Land & Nature","k":24,"d":["Average around \u00a322,900-\u00a325,400, typical range \u00a317,264-\u00a327,336","Shoes and trims horses\u2019 hooves, a genuinely essential, physically demanding skilled trade requiring real precision and animal handling ability","Qualifications: no degree needed \u2192 the Worshipful Company of Farriers apprenticeship is the legally required route (approximately 4 years) \u2192 unlike most trades, it is illegal in the UK to shoe a horse commercially without this qualification"],"u":"https://en.wikipedia.org/wiki/Farrier"},{"t":"Commercial Fisherman","s":"","c":"Land & Nature","k":31,"d":["Average around \u00a331,000-\u00a341,000, though pay varies enormously (range roughly \u00a317,000-\u00a374,000 depending on catch, boat and role)","Qualifications: no formal qualifications required \u2192 commercial fishing training and a fishing licence needed \u2192 genuinely physically demanding, unpredictable-income work"],"u":"https://en.wikipedia.org/wiki/Fisherman"},{"t":"Forester","s":"","c":"Land & Nature","k":38,"d":["Entry-level \u00a334,000-\u00a340,000, experienced foresters similar to slightly higher","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 Forestry/Countryside Management degree or apprenticeship route \u2192 chartered status via the Institute of Chartered Foresters adds a real premium"],"u":"https://en.wikipedia.org/wiki/Forestry"},{"t":"Fish Farm Worker","s":"Aquaculture","c":"Land & Nature","k":22,"d":["Realistic range roughly \u00a318,000-\u00a326,000 depending on experience and employer","Breeds and rears fish (salmon, trout) and shellfish in ponds, tanks, cages or nets, monitoring water quality and health","Qualifications: no formal qualifications required to start \u2192 NVQs/City & Guilds in Aquaculture available for progression \u2192 a genuinely accessible outdoor role in a growing UK food-production sector"],"u":"https://en.wikipedia.org/wiki/Aquaculture"},{"t":"Poultry Farm Worker","s":"","c":"Land & Nature","k":22,"d":["Apprentices start around \u00a320,800, rising with experience toward general agricultural pay bands \u2192 Farm Manager roles (see that entry elsewhere in this guide) considerably higher","Cares for bird welfare, collects eggs, records farm data and maintains strict biosecurity standards","Qualifications: no formal qualifications required \u2192 Level 2 Poultry Worker Apprenticeship provides a genuine structured route \u2192 full UK driving licence usually needed given rural locations"],"u":"https://en.wikipedia.org/wiki/Poultry_farming"},{"t":"Gardener/Horticulturalist","s":"","c":"Land & Nature","k":28,"d":["Apprentices \u00a315,000-\u00a318,500 \u2192 employed gardeners \u00a318,000-\u00a338,000+, Central London roles reaching \u00a334,000-\u00a340,000 \u2192 self-employed with an established client base can earn \u00a340,000-\u00a365,000+, business owners higher still","Genuinely strong demand since 2020 as homeowners invest more in outdoor space","Qualifications: no formal qualifications required to start \u2192 RHS or City & Guilds horticulture qualifications help progression \u2192 switching from employed to self-employed is a real, common route to significantly higher earnings"],"u":"https://en.wikipedia.org/wiki/Horticulture"},{"t":"Sports Groundskeeper/Groundsman","s":"","c":"Land & Nature","k":22,"d":["Distinct from general Gardener elsewhere in this guide - maintains fine turf specifically for football, cricket, rugby and golf to competition standard, a genuinely specialist skill","Average around \u00a318,000-\u00a322,000 \u2192 professional stadium/major ground roles (Premier League, Test cricket venues) considerably higher, \u00a328,000-\u00a335,000+","Qualifications: no formal qualifications required to start \u2192 fine turf/sports pitch maintenance NVQs available for progression \u2192 early starts and outdoor, weather-exposed work in exchange for a genuinely visible role in the sport itself"],"u":"https://en.wikipedia.org/wiki/Groundskeeping"},{"t":"Land Agent/Rural Practice Surveyor","s":"","c":"Land & Nature","k":42,"d":["Distinct from Land Surveyor elsewhere in this guide - values and manages farms, country estates, woodland and forestry, rather than mapping construction sites","Graduate \u00a327,000 \u2192 experienced \u00a340,000-\u00a350,000+ \u2192 chartered/senior \u00a360,000+ \u2192 director/partner level higher still","Genuinely outdoor-office mix, often based in a market town with fieldwork on farms and estates in all weathers","Qualifications: GCSEs \u2192 A-Levels \u2192 RICS-accredited degree \u2192 chartered status via the RICS Assessment of Professional Competence (APC)"],"u":"https://en.wikipedia.org/wiki/Land_agent"},{"t":"Zoologist","s":"","c":"Land & Nature","k":23,"d":["Average around \u00a323,400, genuinely one of the lowest-paid science careers in this whole app","Starting salary as low as \u00a313,800","Senior zoologists with 10-20 years experience average \u00a329,700, with 20+ years reaching \u00a333,600","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Biology essential) \u2192 Zoology degree (3-4 years), often a Master\u2019s or PhD needed for research roles \u2192 honest note: a genuinely competitive field where passion for the work often matters more than pay"],"u":"https://en.wikipedia.org/wiki/Zoology"},{"t":"Marine Biologist","s":"","c":"Land & Nature","k":26,"d":["Distinct from Zoologist elsewhere in this guide - studies specifically ocean and marine life rather than animals generally","Honest reality, same pattern as Zoologist: entry-level as low as \u00a312,000-\u00a314,000 for field assistant/lab technician roles \u2192 PhD holders \u00a326,000-\u00a335,000 \u2192 senior roles in research, consultancy or government up to \u00a345,000+","Qualifications: GCSEs incl. sciences \u2192 A-Levels (Biology essential) \u2192 Marine Biology degree, a Master\u2019s or PhD usually needed for research positions \u2192 genuinely competitive field, often driven more by passion than pay at entry level"],"u":"https://en.wikipedia.org/wiki/Marine_biology"},{"t":"Beekeeper/Apiarist","s":"","c":"Land & Nature","k":28,"d":["Average around \u00a328,036","Highly seasonal work, 35-40 hours a week with long hours in the warmer months, weekends and holiday working often required","Qualifications: no formal qualifications required \u2192 national and local beekeepers\u2019 associations offer training courses \u2192 many combine beekeeping with selling honey and other hive products commercially"],"u":"https://en.wikipedia.org/wiki/Beekeeping"},{"t":"Tree Surgeon/Arborist","s":"","c":"Land & Nature","k":30,"d":["Qualified \u00a323,000-\u00a330,000 \u2192 experienced \u00a330,000-\u00a340,000 \u2192 senior \u00a340,000+, self-employed day rates \u00a3250-\u00a3380","Genuinely physical, sometimes dangerous work climbing and operating chainsaws at height","Qualifications: no formal qualifications required for trainees, full training provided on the job \u2192 NPTC certificates (CS30, CS31, CS38, CS39) required for chainsaw and climbing work \u2192 a full UK driving licence usually needed"],"u":"https://en.wikipedia.org/wiki/Arborist"},{"t":"Vineyard/Viticulture Manager","s":"","c":"Land & Nature","k":43,"d":["Typical range \u00a330,000-\u00a360,000, average around \u00a342,885-\u00a346,634","A genuinely growing UK industry, increasingly technology-embedded and focused on sustainability","Benefits often include subsidised accommodation, vehicle use and production bonuses on top of headline salary","Qualifications: GCSEs \u2192 A-Levels \u2192 Viticulture/Agriculture degree or HND helps but isn\u2019t always essential \u2192 usually builds up through vineyard operative/assistant roles first"],"u":"https://en.wikipedia.org/wiki/Viticulture"},{"t":"Countryside Ranger","s":"National Trust, Wildlife Trusts, RSPB, local authority parks","c":"Land & Nature","k":27,"d":["Typical range \u00a322,000-\u00a334,434 depending on employer and seniority","Operational front-line conservation work - habitat management, visitor engagement, basic species monitoring, working closely with volunteers","Qualifications: GCSEs \u2192 A-Levels or equivalent \u2192 Countryside Management/Conservation degree or apprenticeship helps, not always essential \u2192 genuinely competitive entry given how many people want this outdoor, nature-focused career"],"u":"https://en.wikipedia.org/wiki/Park_ranger"},{"t":"Agronomist","s":"","c":"Land & Nature","k":40,"d":["Average around \u00a336,268-\u00a342,572, typical range \u00a325,420-\u00a373,007, highest-paying regions (Oxford, Shropshire) considerably above average","Advises farmers on crop science, soil health, pest and disease management to maximise yield sustainably","Qualifications: GCSEs incl. sciences \u2192 A-Levels \u2192 Agriculture/Agronomy/Plant Science degree \u2192 BASIS/FACTS professional qualifications required to give commercial pesticide/fertiliser advice"],"u":"https://en.wikipedia.org/wiki/Agronomy"},{"t":"Stable Hand/Groom","s":"horse racing/equestrian industry","c":"Land & Nature","k":20,"d":["Entry-level \u00a317,527-\u00a318,641 \u2192 experienced or head groom \u00a319,000-\u00a325,000+ \u2192 racing yard staff share in a legally-mandated cut of prize money won by horses they care for, on top of wages","Free accommodation, food and sometimes a stable for your own horse often included","Qualifications: no formal qualifications required \u2192 physically demanding, early-starting work (mucking out, feeding, exercising horses) \u2192 a genuine entry route into the wider horse racing industry"],"u":"https://en.wikipedia.org/wiki/Groom_(profession)"},{"t":"Sugar/Cocoa/Palm Oil Plantation Manager","s":"","c":"Land & Nature","k":55,"d":["An explicitly international, expat-style career, since these crops aren\u2019t grown in the UK","Typical package around \u00a355,000-\u00a370,000 equivalent, often WITH significant extras on top - free housing, on-site medical care, work permit and annual flights home all commonly covered by the employer","Usually based in West Africa, Southeast Asia or Latin America, frequently in remote locations described honestly by recruiters as \u201chardship conditions\u201d","Qualifications: GCSEs \u2192 A-Levels \u2192 Agriculture/Agribusiness degree \u2192 several years of farm/plantation experience genuinely required before reaching manager level"],"u":"https://en.wikipedia.org/wiki/Plantation"},{"t":"Veterinary Nurse","s":"","c":"Land & Nature","k":29,"d":["Average around \u00a328,900-\u00a331,000","Qualifications: GCSEs incl. sciences \u2192 A-Levels or equivalent \u2192 2-3 year Veterinary Nursing diploma or degree \u2192 register with the Royal College of Veterinary Surgeons \u2192 a genuinely accessible way into animal care without the extreme competitiveness of full veterinary medicine"],"u":"https://en.wikipedia.org/wiki/Veterinary_nursing"},{"t":"Refuse Collector/Council Worker","s":"bin collection, street cleansing","c":"Land & Nature","k":25,"d":["Entry-level \u00a317,000-\u00a324,000 \u2192 experienced or HGV-licensed drivers \u00a325,000-\u00a333,000+, London higher still","Qualifications: no formal qualifications required to start \u2192 usually employed directly by the local council or a contractor \u2192 gaining an HGV licence while in the job significantly increases pay \u2192 essential public health work, genuinely accessible with no exams needed"],"u":"https://en.wikipedia.org/wiki/Waste_collector"},{"t":"League Two Footballer","s":"4th tier","c":"Sport & Arts","k":60,"d":["Realistic comparison to the Premier League stars elsewhere in this guide","Average around \u00a3100,000/year (\u00a32,000/week), though young/fringe players can earn as little as \u00a312,000-\u00a325,000","Pathway: academy from age 8-9 \u2192 scholarship at 16 \u2192 professional contract at 17-18","Extremely competitive - the overwhelming majority of academy players never turn professional at all"],"u":"https://en.wikipedia.org/wiki/EFL_League_Two"},{"t":"Championship Footballer","s":"2nd tier","c":"Sport & Arts","k":520,"d":["Average around \u00a3520,000/year (\u00a310,000/week)","Still a huge gulf below the Premier League\u2019s top earners, who can earn this much in a single week","Pathway: same academy route as League Two, but only a small fraction of professional footballers ever reach this level"],"u":"https://en.wikipedia.org/wiki/EFL_Championship"},{"t":"Football Referee","s":"","c":"Sport & Arts","k":38,"d":["The same reality-check pyramid as the footballer entries elsewhere in this guide","Grassroots/amateur: \u00a320-\u00a350 per match, most officials have another full-time job and referee as supplementary income \u2192 semi-professional (National League, Select Group 2 EFL): \u00a338,500-\u00a342,000 basic \u2192 Premier League (Select Group 1, just 21 full-time officials in the entire country): \u00a370,000-\u00a3200,000 basic plus \u00a31,150-\u00a32,000 per match, averaging around \u00a3180,000 total","Qualifications: no degree needed \u2192 FA refereeing course (weeks, not years) \u2192 years of grassroots/semi-pro experience needed to be selected for the professional tiers"],"u":"https://en.wikipedia.org/wiki/Association_football_referee"},{"t":"Working Actor","s":"","c":"Sport & Arts","k":43,"d":["Realistic comparison to Hollywood stars elsewhere in this guide","97% of Equity (the actors\u2019 union) members earn UP TO \u00a343,000/year, meaning almost all earn less than that","A 2018 survey found 68% of actors, dancers and musicians earned under \u00a35,000 in a year, with 66% needing a second job","A consistently-working West End actor (not a star) might earn \u00a355,000-\u00a360,000/year, but that level of steady work is rare","Compare to a lead in a hit show, who can earn \u00a310,000-\u00a330,000 PER WEEK - a tiny top tier almost nobody reaches"],"u":"https://en.wikipedia.org/wiki/Equity_(trade_union)"},{"t":"Working Musician","s":"","c":"Sport & Arts","k":21,"d":["Realistic comparison to music superstars elsewhere in this guide","The UK Musicians\u2019 Census (nearly 6,000 musicians surveyed) found average income FROM MUSIC WORK is just \u00a320,700/year, well below the UK average salary of \u00a333,402","43% earn under \u00a314,000/year from music alone","Most professional musicians (70%) hold a degree, yet over half need a second income source to sustain a music career"],"u":"https://en.wikipedia.org/wiki/Musicians%27_Union"}],
  tax: [{"t":"PAYE (how it reaches the taxman)","b":"PAYE","d":"Your employer MUST take Income Tax and your National Insurance out of your pay before you receive it, and send it to HMRC. This system is called PAYE (Pay As You Earn). What is left is your take-home pay \u00b7 2026/27","u":"https://www.gov.uk/paye-for-employers"},{"t":"Personal Allowance","b":"\u00a312,570","d":"\u00a30 to \u00a312,570 \u00b7 0% Income Tax \u00b7 Everyone gets this much tax-free each year before Income Tax starts to apply \u00b7 Tapered away \u00a31 for every \u00a32 earned above \u00a3100,000, gone completely by \u00a3125,140 \u00b7 2026/27 \u00b7 Frozen at this level since 2021","u":"https://en.wikipedia.org/wiki/Personal_allowance"},{"t":"Basic Rate","b":"20%","d":"\u00a312,571 to \u00a350,270 \u00b7 20% Income Tax \u00b7 The rate most UK taxpayers pay on their income within this band \u00b7 2026/27 \u00b7 Scotland sets its own Income Tax bands","u":"https://en.wikipedia.org/wiki/Income_tax_in_the_United_Kingdom"},{"t":"Higher Rate","b":"40%","d":"\u00a350,271 to \u00a3125,140 \u00b7 40% Income Tax \u00b7 Applies once total income passes \u00a350,270 - this is where Career Guide\u2019s higher-paid roles start losing a much bigger share \u00b7 2026/27","u":"https://en.wikipedia.org/wiki/Income_tax_in_the_United_Kingdom"},{"t":"Additional Rate","b":"45%","d":"Over \u00a3125,140 \u00b7 45% Income Tax \u00b7 The UK\u2019s top rate of Income Tax, on everything earned above this threshold \u00b7 2026/27","u":"https://en.wikipedia.org/wiki/Income_tax_in_the_United_Kingdom"},{"t":"National Insurance (Employee)","b":"8% / 2%","d":"8% on earnings between \u00a312,570 and \u00a350,270, then 2% above that \u00b7 Paid on top of Income Tax straight out of every payslip, and funds the NHS and the State Pension \u00b7 2026/27 \u00b7 The same rates apply across the whole UK, including Scotland","u":"https://en.wikipedia.org/wiki/National_Insurance"},{"t":"Tax Code (1257L)","b":"1257L","d":"The standard tax code for 2026/27 \u00b7 Your employer uses it to work out how much of your pay is tax-free: take the number and multiply by 10 (1257 \u00d7 10 = \u00a312,570, the Personal Allowance) \u00b7 The letter L means you get the standard allowance \u00b7 Codes ending W1, M1 or X are temporary emergency codes \u00b7 You can find yours on your payslip or in your HMRC personal tax account","u":"https://en.wikipedia.org/wiki/Income_tax_in_the_United_Kingdom"},{"t":"Employer's National Insurance (on top of your pay)","b":"15%","d":"Your employer also pays its own National Insurance of 15% on everything you earn above \u00a35,000 a year. It is never taken from your pay: it is an extra cost to the employer, so you cost more to employ than your salary \u00b7 2026/27","u":"https://www.gov.uk/guidance/rates-and-thresholds-for-employers-2026-to-2027"},{"t": "Living together but not married: inheritance", "b": "Couples", "d": "Married couples and civil partners can leave everything to each other free of inheritance tax, and the survivor can also use the first person\u2019s unused tax-free band. An unmarried partner gets neither. Anything you leave your partner above your own \u00a3325,000 nil-rate band is taxed at 40%. Each of you has your own \u00a3175,000 residence nil-rate band for a home left to a child or grandchild, but it cannot be passed between partners. With no will, an unmarried partner inherits nothing under the intestacy rules in England and Wales, and the children share the estate. From 6 April 2027 most unused pensions also count towards the estate \u00b7 2026/27", "u": "https://www.gov.uk/inheritance-tax"},{"t": "Living together but not married: tax and benefits", "b": "Couples", "d": "Gifts between spouses are made at no gain or loss for Capital Gains Tax. Between unmarried partners a gift is usually treated as a sale at market value, so a gain above the \u00a33,000 annual exempt amount can be taxed. Marriage Allowance, which moves \u00a31,260 of allowance and saves up to \u00a3252 a year, is only for married couples and civil partners. Bereavement Support Payment can be claimed by an unmarried partner who was living with the person as if married, but only if a child living with them qualified for Child Benefit, or they were pregnant. Otherwise each partner is taxed separately on their own income \u00b7 2026/27", "u": "https://www.gov.uk/marriage-allowance"}],
  takeHome: function (grossK) {
    var gross = grossK * 1000, pa = 12570;
    if (gross > 100000) pa = Math.max(0, pa - Math.floor((gross - 100000) / 2));
    var taxable = Math.max(0, gross - pa);
    var inc = Math.min(taxable, 37700) * 0.20 + Math.min(Math.max(0, taxable - 37700), 125140 - 37700) * 0.40 + Math.max(0, taxable - 125140) * 0.45;
    var ni = Math.min(Math.max(0, gross - 12570), 50270 - 12570) * 0.08 + Math.max(0, gross - 50270) * 0.02;
    var erni = Math.max(0, gross - 5000) * 0.15;
    return { gross: gross, lines: [{ l: 'Income Tax', a: inc }, { l: 'National Insurance (8% / 2%)', a: ni }],
             net: gross - inc - ni, employer: [{ l: 'Employer National Insurance (15% above £5,000)', a: erni }] };
  }
});
